(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["bs"] = {"ui":{"skip":"Preskoči na sadržaj","back":"← Nazad na AI-gile","lang.button":"Jezik: {name}","lang.dialog":"Odaberi jezik","lang.search":"Traži jezike","lang.none":"Nijedan jezik ne odgovara","lang.notYet":"{name} još nije preveden","theme.aria":"Promijeni temu: svijetla, tamna ili crna","theme.toLight":"Prebaci na svijetlu temu","theme.toDark":"Prebaci na tamnu temu","theme.toBlack":"Prebaci na crnu temu (prava crna, blaga za OLED ekrane)","words.underline":"Podvuci ove riječi na stranici","words.underlineHelp":"Pređi mišem preko riječi s tačkicama ili je dodirni da vidiš šta znači.","words.col.todo":"Trenutno odabrane kartice: tim sljedeće počinje s njima.","words.col.doing":"Jedan AI trenutno radi na ovoj kartici.","words.col.review":"Jedan AI je završio posao; drugi ga provjerava prije nego stigne do tebe.","words.col.verify":"Čeka tebe: isprobaj i reci radi li.","words.col.team":"Tvoje bilješke ili odgovori, čekaju da ih tim preuzme.","words.col.done":"Završeno i prihvaćeno.","index.title":"AI-gile: tvoj AI razvojni tim, na jednoj tabli","index.description":"AI-gile je kanban tabla za AI timove koji programiraju. Rade dok ti spavaš; ti dobiješ jednu kratku hrpu stvari za odluku, testiranje i prihvatanje.","hero.logoAlt":"Ikona AI-gile table","hero.h1.html":"Tvoj AI razvojni tim, na jednoj&nbsp;tabli.","hero.alpha":"🐣 Zatvorena pre-alfa","hero.alphaTitle":"Rano i nedovršeno: hvala što isprobavaš!","hero.lede":"Grade dok ti spavaš. Probudiš se uz jednu kratku hrpu: nekoliko pitanja, nekoliko stvari za testiranje, jedan ili dva ljubičasta dijamanta. Klik, prihvaćeno, nazad na kafu.","dl.windows":"Windows aplikacija","dl.browser":"Pokreni u pregledniku","dl.messenger":"📱 Messenger za tvoj telefon","dl.soon":"Uskoro","dl.notify":"🔔 Javi mi kad se otvori","dl.notifySmall":"Alfa ili beta","hero.secondary":"Agile, ali tim nikad ne treba kafu uz stand-up. (Stand-up ipak održavaju.)","pitch.h2":"AI-gile u onoliko riječi koliko želiš","pitch.lede":"Odaberi dužinu, od jedne riječi do 144. Svaka dužina je poseban opis, napisan baš za tu veličinu. Povuci klizač ili koristi tipke sa strelicama.","pitch.rangeLabel":"Dužina u riječima","pitch.dice":"🎲 druga verzija","pitch.words.one":"{n} riječ","pitch.words.other":"{n} riječi","pitch.letters.one":"{n} slovo","pitch.letters.other":"{n} slova","pitch.chars.one":"{n} znak","pitch.chars.other":"{n} znakova","count.line.html.one":"{n} kartica na tabli upravo sada","count.line.html.other":"{n} kartica na tabli upravo sada","people.humans.html.one":"👥 {n} čovjek","people.humans.html.other":"👥 {n} ljudi","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} agenata","people.working.html.one":"⚡ {n} radi upravo sada","people.working.html.other":"⚡ {n} radi upravo sada","pre.title":"AI-gile: ovdje se nešto gradi","pre.description":"Ovdje se nešto gradi. Tabla na kojoj AI timovi grade ono što tražiš i usput te uče. Za sada zatvorena pre-alfa s prijateljima.","pre.h1":"Ovdje se nešto gradi. 🤫","pre.line":"Tabla na kojoj AI timovi grade ono što tražiš i usput te uče. Za sada zatvorena pre-alfa s prijateljima.","pre.btn":"🔔 Javi mi kad se otvori","pre.peek":"Iza stakla: prava tabla, uživo. Svaka kartica je obojena traka.","pre.peekFake":"Iza stakla: ovako izgleda tabla u radu.","pre.night":"🌙 Noćni čuvar je zadužen · 😴 čovjek odmara","features.aria":"Šta radi","f.pile.h":"Jedna hrpa za tebe","f.pile.html":"<b>Za tebe</b> okuplja sve što čeka na tebe, kroz sve projekte: pitanja, stvari za testiranje, zadatke koje može uraditi samo čovjek. Tvoj red kaže šta je sljedeće i koliko traje.","f.sleep.h":"Timovi koji rade dok ti spavaš","f.sleep.p":"Svaki projekt ima lead i tim AI agenata. Komentariši karticu i tim se budi, odradi posao i vrati ti ga s koracima koje može pratiti i umoran čovjek.","f.tester.h":"Prvo provjerava AI tester","f.tester.p":"Prije nego išta stigne do tebe, tester prođe korake u kopiji aplikacije i pokaže šta je vidio, sa snimkom ekrana. Prelistaj one koje su prošle i prihvati jednim klikom.","f.proof.h":"Dokazi, a ne obećanja","f.proof.p":"Svaka predaja pokazuje šta se promijenilo: datoteke, razlike, snimke ekrana. Ne moraš otvarati svaku aplikaciju da vidiš je li gotovo.","f.chat.h":"Čavrljaj sa svojim leadovima","f.chat.p":"Traka u stilu Discorda: jedna ikona po projektu, ljubičasti dijamanti za ono što treba tebe. Pošalji leadu ideju; pretvorit će je u kartice i plan, uz dugme ✅ Go.","f.tidy.h":"Sam održava red","f.tidy.p":"Srodne kartice se spajaju u jednu, zbrkani naslovi se popravljaju, a provjera tokena drži kod vitkim. Manje stvari između kojih prebacuješ, manje razmišljanja.","f.private.h":"Tvoje, na tvom računaru","f.private.li1":"Tabla radi na tvom vlastitom računaru i odgovara samo tebi.","f.private.li2":"Privatne poruke među ljudima su šifrovane od kraja do kraja.","f.private.li3":"Bez računa, bez trackera, bez kolačića.","f.lang.h":"Na tvom jeziku","f.lang.p":"Preko 120 jezika, od holandskog, velškog i japanskog do gusarskog, Yode i klingonskog, uz brzo prebacivanje na engleski za stručne izraze.","f.service.h":"Od ideje do pravog servisa","f.service.p":"Napravio si s AI-jem nešto što ljudi sada koriste? Označi to kao servis i ploča ti pomaže da ga dobro vodiš: provjere dostupnosti, javna stranica statusa, incidenti s analizom, promjene kojima treba Go, sigurnosne kopije koje se provjeravaju svaki dan. Pomoć te uči svaki korak usput.","msgr.h2":"AI-gile Messenger: tvoj tim u džepu","msgr.p1":"Razgovaraj sa svojim AI timom bez otvaranja ploče. Dopisuj se s voditeljima projekata i prijateljima, pogledaj korake testiranja kartice i odgovori na njih, sve s telefona.","msgr.p2":"Za povezivanje skeniraj QR kod na svojoj ploči. Prvi put? Prijateljski demo razgovor će te provesti kroz sve.","msgr.when":"Prvo Android, zatim web verzija za telefone i iPhone.","msgr.who":"Tvoj voditelj projekta","msgr.b1":"Popravka tamnog načina je spremna. Hoćeš korake testiranja?","msgr.b2":"Da, molim!","msgr.b3":"1. Otvori Postavke. 2. Odaberi Tamna. Izgleda li dobro?","tl.aria":"Vremenska crta od prvog razgovora do plana razvoja","tl.h2":"Od prvog četa do onoga što slijedi","tl.lede":"Pravi datumi i vremena, u tvojoj vremenskoj zoni. Poslije danas je plan, bez obećanih datuma.","tl.today":"Danas","tl.planned":"planirano","tl.doing":"u toku","tl.cards.one":"{n} kartica","tl.cards.other":"{n} kartica","join.h2":"Pridruži se","join.lede":"AI-gile gradi jedan bradati čudak s AuDHD-om i nekoliko bitaka s mentalnim zdravljem, i veliki broj strpljivih agenata. Za sada je privatan, u zatvorenoj alfi s prijateljima. Želiš li probati kad se otvori?","join.btn":"Prijavi interes","join.small":"Poslat ćemo ti e-mail, ništa drugo","footer.tag":"AI-gile. Bez trackera, bez kolačića, bez kafe uz stand-up.","footer.licence":"Poslovna licenca","footer.status":"Status","footer.privacy":"Šta čuvamo","footer.thanks":"Pozivi zahvaljujući ChilledChat","form.sending":"Šaljem…","form.failed":"Nije uspjelo: pokušaj ponovo kasnije.","form.offline":"Nije moguće doći do AI-gile: pokušaj ponovo kasnije.","form.keep":"Ovo koristimo samo da ti odgovorimo, a onda ga brišemo. Bez trackera, bez kolačića.","form.keepLink":"Šta čuvamo","interest.title":"AI-gile: javi mi kad se otvori alfa","interest.description":"Ostavi e-mail da saznaš kad se otvori zatvorena alfa ili beta AI-gile.","interest.h1":"🔔 Javi mi kad se otvori","interest.lede":"AI-gile je u zatvorenoj pre-alfi. Ostavi e-mail i javit ćemo ti se jednom, kad bude mjesta za tebe.","interest.email":"Tvoj e-mail","interest.which":"Koje testiranje?","interest.alpha":"Zatvorena alfa: rano, grubo, mnogo promjena","interest.beta":"Beta: stabilnija, kasnije","interest.both":"Bilo koje, šta prije stigne","interest.submit":"Stavi me na listu","interest.thanks":"Hvala! Na listi si.","licence.title":"AI-gile: poslovna licenca","licence.description":"Koristiš li AI-gile u svom poslu? Zatraži besplatnu poslovnu licencu.","licence.h1":"📜 Poslovna licenca","licence.lede":"Koristiš li AI-gile na poslu? Reci nam ko si i čime se baviš. Ako čini nešto dobro, licenca je besplatna.","licence.company":"Firma","licence.website":"Web stranica","licence.what":"Čime se baviš","licence.how":"Kako pomaže svijetu","licence.email":"E-mail","licence.submit":"Prijavi se","licence.thanks":"Hvala! Odgovorit ćemo e-mailom.","status.title":"AI-gile status","status.h1":"AI-gile status","status.quiet":"Sve mirno","status.intro":"Radi li AI-gile upravo sada? Ova stranica svakih 5 minuta provjerava web stranicu, dijeljenje tabli, pozive i preuzimanje.","status.up":"Radi (odgovorio za {ms} ms)","status.slow":"Nije odgovorio na zadnju provjeru, pokušavamo ponovo","status.down":"Ne radi: nije odgovorio na zadnje dvije provjere","status.svc.web":"Web stranica","status.svc.web.offers":"Ova stranica: šta je AI-gile, i obrazac za interes","status.svc.boards":"Dijeljenje tabli","status.svc.boards.offers":"Javne table, poruke među prijateljima i pozivnice","status.svc.calls":"Pozivi","status.svc.calls.offers":"Glas, video i dijeljenje ekrana u AI-gileu","status.svc.download":"Preuzimanje","status.svc.download.offers":"Windows instaler i linkovi za pozivnice","status.checking":"Provjeravam…","status.offline":"Trenutno nije moguće doći do servisa statusa (pokušavam ponovo)","status.updated":"ažurirano {ago}","status.justNow":"upravo sada","status.min":"prije {n} min","status.hours":"prije {n} h","status.days":"prije {n} d","privacy.title":"AI-gile: šta čuvamo","privacy.h1":"Šta čuvamo","privacy.lede":"Ukratko: samo ono što nam pošalješ, i to ne dugo.","privacy.only":"Samo ono što nam pošalješ: ono što upišeš u obrazac, recimo svoj e-mail. Ništa drugo o tebi.","privacy.sealed":"Zapečaćeno je tako da ga naš server ne može pročitati: u tvom pregledniku prije nego što krene (u starijem pregledniku, čim stigne). Samo ga naša vlastita tabla može otvoriti.","privacy.server":"Briše se sa servera čim stigne do naše table. Sve što je tamo i dalje nakon 30 dana svakako se briše.","privacy.board":"Na našoj tabli ga čuvamo samo dok ti ne odgovorimo, a onda ga i tamo brišemo.","privacy.none":"Bez trackera, bez kolačića, bez analitike.","privacy.local":"Tvoj jezik i izbor svijetle ili tamne teme ostaju u tvom pregledniku. Nikad nam se ne šalju.","privacy.ask":"Želiš da nestane ranije? Odgovori na naš e-mail i reci nam.","live.h2":"Gledajte kako se gradi, uživo","live.caption":"Svaka kartica je skrivena: vidite oblik posla, a ne riječi.","live.watching.one":"uživo: {n} gleda","live.watching.other":"uživo: {n} gleda","live.last.now":"Posljednja kartica premještena je upravo sada","live.last.min.one":"Posljednja kartica premještena je prije {n} min","live.last.min.other":"Posljednja kartica premještena je prije {n} min","live.last.hour.one":"Posljednja kartica premještena je prije {n} sat","live.last.hour.other":"Posljednja kartica premještena je prije {n} sati","live.last.day.one":"Posljednja kartica premještena je prije {n} dan","live.last.day.other":"Posljednja kartica premještena je prije {n} dana","live.offline":"Tabla uživo malo odmara. Navratite uskoro.","live.cols":"Backlog|Za uraditi|U toku|Tim provjerava|Za tvoje testiranje|Za tim|Gotovo","pitch.words.few":"{n} riječi","pitch.letters.few":"{n} slova","pitch.chars.few":"{n} znaka","count.line.html.few":"{n} kartice na tabli upravo sada","tl.cards.few":"{n} kartice","footer.models":"AI-gile pokreće AI modele za tebe. Ono što oni kažu i urade je njihovo, zato provjeri prije nego što povjeruješ.","privacy.ai.h":"AI dio","privacy.ai.models":"AI-gile je ploča. Posao rade AI modeli drugih kompanija, kao što su Claude, Codex i Gemini, na tvojim vlastitim računima.","privacy.ai.check":"Ono što pišu i rade potiče od njih i može biti pogrešno. Provjeri prije nego što se osloniš na to ili objaviš.","privacy.ai.files":"Oni mijenjaju datoteke i pokreću komande u folderima koje povežeš. Napravi sigurnosnu kopiju.","privacy.ai.send":"Ono što daš modelu ide kompaniji koja ga pokreće, prema njenim uvjetima. Važe uvjeti i troškovi svakog od njih.","privacy.ai.asis":"AI-gile je rana probna verzija, data onakva kakva jest."},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboti.","Delegirano."]},{"n":2,"texts":["Robotski kanban.","Agenti, organizovano.","Ideje, izgrađene."]},{"n":3,"texts":["Kanban za robote.","Ideje postaju funkcije.","Besplatni agentski kanban."]},{"n":5,"texts":["Kanban tabla koju vode agenti.","Ti pišeš kartice. Agenti grade.","Besplatno, lokalno, testirano, pomalo smiješno."]},{"n":8,"texts":["Besplatna kanban tabla na kojoj rade AI agenti.","Napiši ideju. Agenti je grade. Ti prihvataš.","Agile za jednog čovjeka i mnogo strpljivih robota."]},{"n":13,"texts":["Kanban tabla na tvom računaru na kojoj AI agenti preuzimaju kartice.","Napiši ideju. Tim agenata je izgradi, zatim je tester provjeri, a ti kažeš da.","Besplatno, bez računa, bez trackera: tabla, nekoliko robota i ti kao šef."]},{"n":21,"texts":["AI-gile je kanban tabla za rad s AI agentima koji programiraju. Oni preuzimaju kartice; ti ih testiraš i prihvataš.","Svaki projekt dobije lead i tim AI agenata. Komentariši bilo koju karticu i tim odmah prione na posao.","Besplatna, lična tabla zadataka koja radi na tvom vlastitom računaru. Radnici su roboti. Onaj ko kaže da, to si ti."]},{"n":34,"texts":["Ideje stavljaš na tablu. Tim AI agenata ih pretvara u funkcije koje rade, testira ih i vraća ti ih s koracima za isprobavanje. Ništa se ne računa kao gotovo dok ti to ne kažeš.","AI-gile je domaća kanban tabla koju je Rich napravio uz mnogo pomoći agenata kojima sada upravlja. Besplatna je, radi na tvom računaru i dijeli se s prijateljima, ne prodaje se.","Zamisli običnu kanban tablu, s kolonama od Backloga do Gotovo, samo što kartice preuzimaju AI agenti. Javljaju napredak, pitaju kad zapnu i uvijek čekaju tvoj podignuti palac."]},{"n":55,"texts":["AI-gile je kanban tabla na kojoj tim čine AI agenti. Svaki projekt ima lead koji planira posao i pomoćnike koji ga grade. Kad je funkcija spremna, AI tester je isproba i napravi snimak ekrana, a onda sleti na tvoju hrpu. Prihvati je ili napiši komentar pa je prerade.","Počelo je kao način na koji je jedna osoba pratila mnogo AI programerskih sesija odjednom, a izraslo je u pravu tablu. Radi na tvom računaru, ne traži račun i nema trackera. Besplatna je za prijatelje i znatiželjnike. Također je nedovršena, pa računaj na grube ivice i poneko iznenađenje.","Evo poštene verzije. Ideje i dalje moraš imati ti, a rezultate i dalje moraš provjeriti ti. AI-gile radi sve između: drži kartice u redu, budi pravog agenta kad komentarišeš, pokazuje tačno šta se promijenilo i sve to slaže u jednu kratku hrpu za tebe."]},{"n":89,"texts":["AI-gile je besplatna kanban tabla koju pokrećeš na vlastitom računaru. Umjesto ljudi, svaki projekt ima tim AI agenata: lead koji tvoje ideje pretvara u kartice i plan, i pomoćnike koji kartice preuzimaju po prioritetu. Kad je nešto izgrađeno, AI tester slijedi korake testiranja i pokazuje ti šta je vidio. Zatim čeka u jednoj hrpi koja se zove Za tebe. Ti je prihvatiš, ili komentarišeš pa tim pokuša ponovo. Ništa ne stiže do Gotovo bez tebe.","Nekoliko stvari koje možda ne očekuješ. Noćna straža drži kolonu Za uraditi popunjenom dok ti spavaš, birajući kartice kojima ne treba tvoj odgovor. Brojač tokena pokazuje koliko su agenti potrošili danas i ove sedmice, a No Token Mode im kaže da prestanu trošiti. Možeš pisati prijateljima, a privatne poruke su šifrovane od kraja do kraja. Tabla govori oko 120 jezika, uključujući holandski, flamanski, gusarski i klingonski. Ništa od toga ne košta ni feninga, a niko ti to ni ne pokušava prodati.","AI-gile je mali, lični projekt, a ne firma. Rich je htio voditi nekoliko AI programerskih projekata bez otvaranja svake aplikacije da ih provjeri, pa su on i agenti napravili tablu za to, a onda tablu iskoristili da izgrade ostatak sebe. U zatvorenoj je pre-alfi, što znači da radi, uglavnom, za šaku prijatelja. Nema stranice s cijenama, nema newslettera i nema plana rasta. Ako ti zvuči korisno, možeš zatražiti da probaš kad se malo više otvori."]},{"n":144,"texts":["AI-gile je kanban tabla za jednog čovjeka i mnogo AI agenata. Radi na tvom vlastitom računaru i potpuno je besplatna. Dodaješ projekte, a svaki projekt dobije lead i mali tim. Čavrljaš s leadom, pomalo kao na Discordu, i opišeš ideju; lead je pretvara u kartice i plan, pa čeka da pritisneš Go. Tim kartice rješava po prioritetu, koristeći jednostavnu komandnu liniju napravljenu za jezičke modele. Prije nego se išta vrati tebi, AI tester prođe korake u kopiji aplikacije i priloži snimak ekrana. Gotov posao sleti na tvoju hrpu s promijenjenim datotekama i razlikom. Ti ga prihvatiš, ili ostaviš komentar pa se tim probudi i pokuša ponovo. Samo ti možeš premjestiti karticu u Gotovo. Nema računa, nema trackera i nema kolačića, a sve ostaje na tvom računaru.","Otprilike jedan dan s AI-gile. Navečer ostaviš nekoliko komentara: ovo dugme je na pogrešnom mjestu, ta lista bi trebala biti sortirana, može li tamni mod. Odeš spavati. Agenti pročitaju komentare, naprave izmjene, testiraju ih i vrate ti ih. Ako Za uraditi ostane prazno, noćna straža ga puni iz backloga karticama kojima ne treba tvoj odgovor. Ujutro te čeka jedna kratka hrpa: par pitanja i nekoliko stvari za isprobavanje, svaka s koracima koje može slijediti i pospana osoba i sa snimkom ekrana na kojem radi. Prokliktaš se, prihvatiš dobre, a ostale vratiš. Brojač tokena pokazuje šta je sve to potrošilo, a No Token Mode je tu za štedljive sedmice. Onda doručkuješ, a u tome ti agenti još ne mogu pomoći.","Prvo, šta AI-gile nije. Nije startup, nije na prodaju i niko ne prikuplja tvoje podatke. To je besplatna tabla koja radi na tvom računaru, bez računa, bez trackera i bez kolačića. A šta jeste: jedno uredno mjesto na kojem vidiš sve AI programerske projekte odjednom, s timom agenata koji radi kartice i tobom koji donosiš odluke. Spaja srodne kartice, popravlja zbrkane naslove i pazi koliko kod ostaje vitak. Govori oko 120 jezika, od holandskog i flamanskog do gusarskog i klingonskog. Prijatelji mogu pisati jedni drugima, privatno i šifrovano. Napravili su je Rich i veliki broj strpljivih agenata, uglavnom koristeći nju samu. U zatvorenoj je pre-alfi, pa je na mjestima gruba. Ako ti zvuči zabavno, lijepo pitaj i možda uđeš ranije."]}],"quips":{"1":"Jedna riječ. Hrabro. Možda i previše hrabro.","3":"Tri riječi. Već iskrenije od većine stranica proizvoda.","8":"Osam riječi. I dalje kraće od stand-upa.","21":"Dužine su, usput, story pointi. Naravno da jesu.","55":"Pedeset pet riječi. Dvije kartice su završene dok si čitao.","144":"To je ona duga. Nema 233. Agenti su otišli spavati."}},"timeline":{"first-idea.name":"Prva ideja","first-idea.line":"Sasvim prvi razgovor, prije nego što je postojao ijedan red koda.","first-board.name":"Prva tabla","first-board.line":"Tabla koja prati vlastitu izgradnju: kartice, kolone, prevlačenje, projekti.","team-roles.name":"Tim i uloge","team-roles.line":"Profili agenata, šabloni timova, prostori i ko šta radi.","install.name":"Instalacija i izdanja","install.line":"Zip koji prijatelj može instalirati, samoažuriranje, kanali i vraćanje unazad.","usage-saver.name":"Štednja potrošnje","usage-saver.line":"Mjeri koliko koštaju pokretanja, drži kod vitkim, čuvaj svoj limit.","friends.name":"Prijatelji i dijeljenje","friends.line":"Privatne poruke, šifrovani relej, pozivnice, uloge i zajednički projekti.","languages.name":"Jezici","languages.line":"Svaki tekst na ekranu u jezičkoj datoteci, prvo holandski i flamanski.","ai-tester.name":"AI tester","ai-tester.line":"Tester prvi provjerava svaku predaju i pokazuje šta je vidio.","website.name":"Web stranica","website.line":"aigile.lol, teaser i ova vremenska crta.","streaming.name":"Čet i striming","streaming.line":"Discord, Twitch, OBS, streamerski mod, GIF-ovi i emotikoni.","no-ai.name":"Izdanje bez AI-ja","no-ai.line":"Tabla za ljude koji programiraju bez AI-ja, i javne table.","night-watch.name":"Noćna straža","night-watch.line":"Čuvar i Scrum Master drže timove na zadatku dok ti spavaš.","p-more.name":"Sve ostalo","p-more.line":"Manje ideje koje još čekaju svoj red.","p-android.name":"Telefon i Android","p-android.line":"Do svoje table s telefona, a zatim izvorna Android aplikacija.","p-release.name":"Alfa i dalje","p-release.line":"Zatvorena alfa, živa stranica, pa beta.","p-languages.name":"Više jezika","p-languages.line":"130 jezika i način uranjanja za one koji uče.","p-engines.name":"Više AI motora","p-engines.line":"Izaberi Claude, Codex, Gemini, Copilot ili Cursor za svakog agenta.","p-pro.name":"Profesionalna praksa","p-pro.line":"Oznake rizika, kapije za spajanje, kartice incidenata i zaštitne ograde.","p-self.name":"Briga o tebi","p-self.line":"Mod umora, podsjetnici na brigu o sebi i 4:20.","p-servers.name":"Serveri i rast","p-servers.line":"Globalne postavke servera, uloge i planiranje rasta.","p-livestream.name":"Dodaci za striming","p-livestream.line":"Twitch čet, vlastiti emotikoni i javni prikaz uživo."},"words":{"button":"📖 Stručni izrazi","h":"📖 Objašnjene riječi","intro":"Besplatna obuka običnim jezikom: svaka riječ na koju naiđeš od prve ideje do usluge na koju se ljudi oslanjaju, uz Agile, pravljenje, sigurnost i rad s AI-jem usput.","search":"Traži riječ…","none":"Nijedna riječ se ne poklapa.","close":"Zatvori","count":{"one":"{count} riječ","other":"{count} riječi"},"groups":[{"id":"idea","name":"💡 Ideja i istraživanje"},{"id":"plan","name":"🗺️ Planiranje posla"},{"id":"agile","name":"🔁 Agilni načini rada"},{"id":"build","name":"🛠️ Pravljenje"},{"id":"test","name":"🧪 Testiranje i kvalitet"},{"id":"change","name":"🔀 Sigurno mijenjanje"},{"id":"run","name":"🛎️ Vođenje servisa"},{"id":"sec","name":"🔒 Sigurnost i privatnost"},{"id":"ai","name":"🤖 Rad s AI-jem"},{"id":"money","name":"💰 Novac i licence"}],"list":[{"id":"discovery","g":"idea","word":"Istraživanje (discovery)","text":"Rana faza u kojoj saznaješ koji problem vrijedi riješiti i za koga, prije nego što se bilo šta napravi.","also":["faza istraživanja","discovery"]},{"id":"problemstmt","g":"idea","word":"Opis problema","text":"Jedna ili dvije rečenice o tome ko ima problem, šta je to i zašto je važno, da svi ciljaju isto.","also":["opisi problema"]},{"id":"user","g":"idea","word":"Korisnik","text":"Osoba koja koristi ono što praviš. Posao se radi zbog njenih potreba.","also":["korisnici"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Zainteresovana strana","text":"Svako kome je stalo kako će posao ispasti ili na koga on utiče, kao oni koji plaćaju, koriste ili podržavaju proizvod.","also":["zainteresovane strane","stakeholder","stakeholderi"]},{"id":"persona","g":"idea","word":"Persona","text":"Izmišljena, ali uvjerljiva osoba koja predstavlja jednu vrstu korisnika, da se tim može pitati: „hoće li Sam ovo smatrati lakim?“","also":["persone"]},{"id":"userresearch","g":"idea","word":"Istraživanje korisnika","text":"Razgovor s pravim ljudima i posmatranje kako rade, da saznaš šta im treba, umjesto da nagađaš.","also":["razgovori s korisnicima"]},{"id":"journey","g":"idea","word":"Put korisnika","text":"Koraci koje osoba prođe da nešto obavi, od prvog saznanja do kraja, i izvan tvog proizvoda. Kad ga nacrtaš, vidiš gdje zapinju.","also":["putevi korisnika","put kupca"]},{"id":"painpoint","g":"idea","word":"Bolna tačka","text":"Nešto što ljude danas nervira ili usporava. Dobri proizvodi uklanjaju bolne tačke.","also":["bolne tačke","pain point"]},{"id":"assumption","g":"idea","word":"Pretpostavka","text":"Nešto u šta vjeruješ, ali to još nije provjereno. Kad pretpostavke zapišeš, vidiš šta prvo treba testirati.","also":["pretpostavke","assumption"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hipoteza","text":"Najbolja procjena koju planiraš provjeriti, s onim što očekuješ da će se desiti, npr. „ljudi će se registrovati ako je prvi mjesec besplatan“.","also":["hipoteze"]},{"id":"experiment","g":"idea","word":"Eksperiment","text":"Mali planirani test da saznaš radi li ideja, prije nego što u nju uložiš mnogo.","also":["eksperimenti"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"Brz, grub pokušaj da vidiš može li ideja uopšte funkcionisati. Obično se baci kad dobiješ odgovor.","also":["PoC","dokaz koncepta","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototip","text":"Rani model proizvoda, često slike po kojima se može klikati, da ideju isprobaš na ljudima prije nego što je napraviš kako treba.","also":["prototipovi"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"Jednostavna skica ekrana koja pokazuje gdje šta ide, bez boja i pravog sadržaja.","also":["wireframes","žičani model","skica ekrana"]},{"id":"mockup","g":"idea","word":"Mockup","text":"Detaljna slika kako će ekran izgledati, sa stvarnim bojama i tekstom, ali još ništa ne radi.","also":["mockups","mock-up","mock-ups","maketa"]},{"id":"bizcase","g":"idea","word":"Poslovno opravdanje (business case)","text":"Razlozi za pokretanje projekta: koliko košta, šta donosi ili štedi i koji su rizici.","also":["business case","poslovni slučaj","opravdanost projekta"]},{"id":"feasibility","g":"idea","word":"Izvodljivost","text":"Može li se nešto zaista napraviti i održavati s vremenom, novcem i znanjem koje imaš.","also":["izvodljivo"]},{"id":"outcome","g":"idea","word":"Ishod","text":"Promjena koju želiš za ljude, npr. manje propuštenih termina. Važnija je od toga koliko se toga napravi.","also":["ishodi"],"noTip":1},{"id":"output","g":"idea","word":"Izlaz (output)","text":"Nešto što tim napravi, poput novog ekrana ili izvještaja. To što je napravljeno ne znači samo po sebi da nekome pomaže.","also":["outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Mjera uspjeha","text":"Broj koji ti kaže je li posao postigao svoj cilj, npr. više ljudi završi narudžbu.","also":["mjere uspjeha"]},{"id":"kpi","g":"idea","word":"Ključni pokazatelj učinka (KPI)","text":"Važan broj koji pratiš da vidiš ide li sve dobro, npr. broj registracija sedmično.","also":["KPI","KPIs","key performance indicator","ključni pokazatelji učinka"]},{"id":"okr","g":"idea","word":"Ciljevi i ključni rezultati (OKR)","text":"Način postavljanja ciljeva: cilj kaže šta želiš, a nekoliko ključnih rezultata su brojevi koji pokazuju da je cilj postignut.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Proizvod","text":"Ono što se pravi i održava za korisnike, kao što je aplikacija, web stranica ili alat.","also":["proizvodi"],"noTip":1},{"id":"vision","g":"plan","word":"Vizija proizvoda","text":"Kratka izjava o tome kome proizvod pomaže i kamo ide dugoročno.","also":["vision statement","izjava o viziji"]},{"id":"po","g":"plan","word":"Vlasnik proizvoda (PO)","text":"Osoba koja odlučuje šta se pravi i kojim redom, da tim uvijek radi ono što je najvažnije. U AI-gileu to si ti.","also":["PO","product owner","vlasnici proizvoda"]},{"id":"pm","g":"plan","word":"Menadžer proizvoda (PM)","text":"Osoba koja vodi računa o pravcu proizvoda: koje probleme rješava, za koga i zašto. PM može značiti i menadžer projekta, pa provjeri koje.","also":["product manager","menadžeri proizvoda"]},{"id":"projmgr","g":"plan","word":"Menadžer projekta","text":"Osoba koja drži projekat u roku i budžetu i prati ko šta radi i do kada.","also":["project manager","menadžeri projekata","voditelj projekta"]},{"id":"roadmap","g":"plan","word":"Plan razvoja (roadmap)","text":"Grub plan onoga što dolazi narednih mjeseci, redom. Pokazuje pravac, a ne tačne datume, i mijenja se kako učiš.","also":["roadmap","roadmaps","mapa puta"]},{"id":"milestone","g":"plan","word":"Prekretnica","text":"Tačka u projektu koju vrijedi obilježiti, npr. „prva verzija objavljena“ ili „100 korisnika“.","also":["prekretnice","milestone"]},{"id":"mvp","g":"plan","word":"Minimalni upotrebljivi proizvod (MVP)","text":"Najmanja verzija proizvoda koja je ipak korisna stvarnim ljudima, da rano učiš od njih.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Zahtjev","text":"Nešto što gotov proizvod mora raditi ili biti.","also":["zahtjevi","requirement"],"noTip":1},{"id":"scope","g":"plan","word":"Opseg posla (scope)","text":"Šta je uključeno u posao i, jednako važno, šta nije.","also":["scope","u opsegu","van opsega"]},{"id":"scopecreep","g":"plan","word":"Širenje opsega (scope creep)","text":"Kad se poslu malo-pomalo dodaje sve više, a niko se nije dogovorio o dodatnom vremenu ili troškovima, pa se nikad ne završi.","also":["scope creep","feature creep"]},{"id":"feature","g":"plan","word":"Funkcionalnost","text":"Jedna stvar koju proizvod može uraditi za ljude, npr. „postavi novu lozinku“.","also":["funkcionalnosti","feature","features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"Veliki komad posla, prevelik za jedan put, pa se podijeli na manje kartice.","also":["epics","epik"]},{"id":"story","g":"plan","word":"Korisnička priča","text":"Mali komad posla napisan iz ugla korisnika: „Kao kupac želim sačuvati korpu da mogu završiti kasnije.“ Otvara razgovor o tome šta napraviti.","also":["user story","korisničke priče"]},{"id":"ac","g":"plan","word":"Kriteriji prihvatanja (AC)","text":"Provjere koje kartica mora proći da bi se računala kao gotova, dogovorene prije početka, npr. „korpa je još tu nakon što se odjavim i ponovo prijavim“.","also":["acceptance criteria"]},{"id":"task","g":"plan","word":"Zadatak","text":"Jedan posao koji treba uraditi, često mali korak veće priče.","also":["zadaci","task","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Tiket","text":"Drugi naziv za karticu: jedan komad posla ili jedan zahtjev koji se prati od početka do kraja.","also":["tiketi","ticket","tickets"]},{"id":"priority","g":"plan","word":"Prioritet","text":"Koliko je nešto važno ili hitno u poređenju sa svim ostalim, da najvažniji posao ide prvi.","also":["prioriteti"],"noTip":1},{"id":"prioritise","g":"plan","word":"Određivanje prioriteta","text":"Slaganje posla po važnosti. Čest način je MoSCoW: Must have (mora), Should have (trebalo bi), Could have (moglo bi), Won't have (ovaj put ne).","also":["prioritizacija","MoSCoW"]},{"id":"estimate","g":"plan","word":"Procjena","text":"Najbolja pretpostavka o veličini ili trajanju posla. To je pretpostavka, a ne obećanje.","also":["procjene","estimate","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"Način procjene veličine posla poređenjem kartica jedne s drugom („otprilike dvostruko veća od one“), umjesto u satima. Ne služe za poređenje timova.","also":["story point","bodovi priče"]},{"id":"tshirt","g":"plan","word":"T-shirt veličine","text":"Procjena veličine posla kao S, M, L ili XL. Brzo i dovoljno dobro za rano planiranje.","also":["t-shirt sizes","veličine majica"]},{"id":"poker","g":"plan","word":"Planning poker","text":"Igra za procjenu: svi istovremeno pokažu kartu s veličinom, pa najviša i najniža objasne zašto.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Zavisnost","text":"Kad jedan komad posla ne može početi ili završiti dok se ne završi drugi.","also":["zavisnosti","dependency"]},{"id":"blocker","g":"plan","word":"Blokada","text":"Sve što trenutno sprečava napredak posla, npr. odgovor koji nedostaje ili pokvaren alat.","also":["blokade","blocker"]},{"id":"deadline","g":"plan","word":"Rok","text":"Datum do kojeg nešto mora biti gotovo.","also":["rokovi","deadline"],"noTip":1},{"id":"deliverable","g":"plan","word":"Isporuka","text":"Nešto opipljivo što posao proizvede i preda, npr. stranica koja radi ili izvještaj.","also":["isporuke","deliverable"]},{"id":"forecast","g":"plan","word":"Prognoza","text":"Predviđanje šta će se vjerovatno desiti, npr. kad će posao biti gotov, na osnovu onoga što do sada znaš.","also":["prognoze","forecast"],"noTip":1},{"id":"metric","g":"plan","word":"Metrika","text":"Sve što mjeriš i pratiš kroz vrijeme, npr. posjete stranici ili koliko traje popravka.","also":["metrike","metric"]},{"id":"feedback","g":"plan","word":"Povratne informacije","text":"Ono što ti ljudi kažu o tvom radu, dobro i loše. Dobiti ih rano i često je srž Agilea.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Lista čekanja ideja i posla koji još nisu isplanirani, s najvažnijim na vrhu. Ništa se iz nje ne radi dok se ne premjesti u Za uraditi."},{"id":"sprint","g":"agile","word":"Sprint","text":"Kratak, fiksan period rada (često jedna ili dvije sedmice, nikad više od mjesec dana) s ciljem i dogovorenim skupom kartica za završiti.","also":["sprintovi","sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Brza dnevna provjera: šta je ko radio, šta radi dalje i šta ga koči. U Scrumu se zove dnevni scrum.","also":["standup","stand-ups","daily scrum","daily stand-up","dnevni sastanak"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Način rada u kojem kartice putuju kroz kolone ploče (kao Za uraditi, U toku, Gotovo), a tim ograničava koliko je istovremeno u toku, da posao teče."},{"id":"wip","g":"agile","word":"WIP limit","text":"WIP je skraćeno od work in progress (posao u toku). WIP limit je najveći broj kartica koje kolona smije držati odjednom, da tim završi stvari prije nego što počne nove.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definicija Završeno","text":"Kratka timska lista šta „gotovo“ znači, recimo testirano i objašnjeno, prije nego što ti se kartica preda. Njen blizanac, Definicija Spremno, kaže kad je kartica dovoljno jasna da se počne.","also":["Definition of Ready","DoD","DoR","definicija gotovog"]},{"id":"retro","g":"agile","word":"Retro","text":"Redovan osvrt na to kako tim radi, da se dogovore jedna ili dvije stvari koje će sljedeći put uraditi bolje. Skraćeno od retrospektiva. U AI-gileu retro predlaže promjenu u načinu rada tima, a ti kažeš Go ili Još ne.","also":["retrospektiva","retrospektive","retrospective"]},{"id":"swarm","g":"agile","word":"Roj","text":"Svi na zadatak: mnogo ljudi ostavi drugi posao da zajedno riješe jednu hitnu stvar dok se ne sredi. U AI-gileu svaki tim pomaže na jednom projektu, a ostali projekti u međuvremenu čekaju.","also":["swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"U Scrumu, osoba koja pomaže timu da dobro radi: uklanja ono što ga koči, drži sastanke na tragu i podučava dobre navike, bez zapovijedanja. U AI-gileu Lead Scrum Master uočava zaglavljene kartice, podstiče timove i podsjeća te na ono što čeka, kroz sve projekte.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"Način rada u malim koracima: napraviš malo, često pokažeš stvarne rezultate, učiš iz onoga što ljudi kažu i mijenjaš plan usput, umjesto da sve planiraš unaprijed.","also":["Agile development","agilni razvoj","agilni način rada"]},{"id":"manifesto","g":"agile","word":"Agile manifest","text":"Kratka izjava koju su 2001. napisali ljudi koji prave softver. Ljude, rezultate koji rade, blisku saradnju s klijentima i prilagođavanje promjenama stavlja ispred teških planova i papirologije.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"Stariji način rada: isplaniraš sve, pa sve napraviš, pa sve testiraš, jedna faza za drugom. Promjene pri kraju su teške i skupe.","also":["waterfall model","vodopad"]},{"id":"iteration","g":"agile","word":"Iteracija","text":"Jedan krug pravljenja nečega, provjere i poboljšanja. Agile rad je lanac takvih krugova, a sprint je jedna njihova vrsta.","also":["iteracije","iteration"]},{"id":"increment","g":"agile","word":"Inkrement","text":"Novi komad koji radi, dodan proizvodu u sprintu ili krugu rada, a uklapa se u ono što je već postojalo.","also":["inkrementi","increment"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Popularan Agile način rada: mali tim radi u kratkim sprintovima prema cilju, s određenim ulogama i nekoliko redovnih sastanaka za planiranje, provjeru i poboljšanje."},{"id":"scrumteam","g":"agile","word":"Scrum tim","text":"Mala grupa koja radi posao u Scrumu: vlasnik proizvoda, Scrum Master i developeri.","also":["Scrum timovi"]},{"id":"ceremonies","g":"agile","word":"Scrum događaji","text":"Redovni sastanci u Scrumu: planiranje sprinta, dnevni scrum, pregled sprinta i retro. Mnogi ih zovu ceremonijama.","also":["ceremonies","Scrum ceremonies","ceremonije"]},{"id":"sprintplan","g":"agile","word":"Planiranje sprinta","text":"Sastanak na početku sprinta na kojem se tim dogovori zašto je sprint važan, koje kartice preuzima i kako početi.","also":["sprint planning","sastanak za planiranje"]},{"id":"sprintgoal","g":"agile","word":"Cilj sprinta","text":"Jedna rečenica koja kaže čemu sprint služi. Sitni zadaci se mogu mijenjati usput, sve dok se cilj ostvari.","also":["ciljevi sprinta","sprint goal"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"Kartice odabrane za tekući sprint, s planom tima za njihovo odrađivanje.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"Cijela uređena lista svega što bi se moglo napraviti za proizvod, najvažnije na vrhu. Stalno se mijenja kako učiš.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Cilj proizvoda","text":"Veći rezultat prema kojem proizvod ide, što timu pomaže da odabere šta dalje.","also":["ciljevi proizvoda","product goal"]},{"id":"refinement","g":"agile","word":"Dorada backloga","text":"Redovno pregledanje backloga da bi se kartice sredile, podijelile, poredale i dobile više detalja, kako bi bile spremne za preuzimanje. Zove se i backlog grooming.","also":["backlog refinement","backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Pregled sprinta","text":"Sastanak na kraju sprinta na kojem tim pokaže šta je završio i čuje šta ljudi misle, da bi odlučio šta slijedi.","also":["sprint review","sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Pokazivanje gotovog posla kako radi, uživo, ljudima koji su ga tražili.","also":["demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"Fiksna količina vremena za nešto. Kad istekne, staneš, čak i ako nije sve gotovo.","also":["timeboxed","timeboxes","vremenski okvir"]},{"id":"velocity","g":"agile","word":"Brzina (velocity)","text":"Koliko posla tim obično završi u sprintu, što služi da se isplanira koliko preuzeti sljedeći put. Nije ocjena koliko se ljudi trude.","also":["velocity","team velocity"]},{"id":"capacity","g":"agile","word":"Kapacitet","text":"Koliko posla tim može preuzeti u nekom periodu, nakon godišnjih odmora i drugih poslova.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown grafikon","text":"Grafikon preostalog posla u sprintu koji pada iz dana u dan. Ako linija ostane ravna, nešto je zapelo.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup grafikon","text":"Grafikon završenog posla koji raste kroz vrijeme, uz ukupno planirano, da vidiš kad ćeš stići.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban ploča","text":"Sama ploča: jedna kolona za svaku fazu posla, a kartice putuju preko nje.","also":["Kanban boards"]},{"id":"pullsys","g":"agile","word":"Pull sistem","text":"Način rada u kojem novi posao počinje tek kad neko ima mjesta da ga preuzme, umjesto da mu se natovari na već pun tanjir.","also":["pull-based","pull system"]},{"id":"flow","g":"agile","word":"Tok (flow)","text":"Koliko glatko posao ide preko ploče. Dobar tok znači da se kartice stalno kreću, a ne gomilaju.","also":["flow of work","tok posla"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"Koliko traje od trenutka kad neko nešto zatraži do trenutka kad je gotovo.","also":["lead times","vrijeme isporuke"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"Koliko kartici treba od trenutka kad se na njoj zaista počne raditi do trenutka kad je gotova.","also":["cycle times","vrijeme ciklusa"]},{"id":"throughput","g":"agile","word":"Propusnost (throughput)","text":"Koliko se kartica završi sedmično, ili u bilo kom zadatom vremenu.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Usko grlo","text":"Jedna faza u kojoj se posao gomila i usporava sve iza nje, kao uski vrat boce.","also":["bottlenecks","uska grla"]},{"id":"swimlane","g":"agile","word":"Staza (swimlane)","text":"Red preko ploče koji grupiše kartice jedne vrste, npr. hitan posao ili kartice jednog tima.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"Način rada koji uklanja rasipanje (sve što ne pomaže klijentu) i drži posao u toku."},{"id":"waste","g":"agile","word":"Rasipanje (waste)","text":"U Leanu, sve što traži trud, a ne pomaže klijentu, kao čekanje, prerada ili pravljenje stvari koje niko ne koristi.","noTip":1},{"id":"kaizen","g":"agile","word":"Stalno poboljšanje","text":"Postepeno, stalno napredovanje kroz sitne redovne promjene, uz provjeru jesu li pomogle. Retro je jedan od načina. Zove se i kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Samoorganizovani tim","text":"Tim koji sam odlučuje kako će raditi posao, umjesto da mu se govori korak po korak.","also":["self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Multifunkcionalni tim","text":"Tim koji ima sve vještine potrebne da sam završi posao, kao dizajn, pravljenje i testiranje.","also":["cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"Kratko istraživanje ograničeno vremenom, kojim se odgovara na pitanje prije nego što se krene u pravi posao.","also":["spikes"]},{"id":"rework","g":"agile","word":"Prerada","text":"Ponovno odrađivanje posla zato što prvi put nije bio dobar.","also":["reworked"]},{"id":"safe","g":"agile","word":"Skalirani Agile (SAFe)","text":"Načini primjene Agilea kroz mnogo timova u velikoj organizaciji. SAFe (Scaled Agile Framework) je jedan poznat primjer.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Projektni folder s kodom i cijelom historijom commitova. Može biti na tvom računaru, na GitHubu, ili na oba mjesta.","also":["repozitorij","repository"]},{"id":"branch","g":"build","word":"Branch","text":"Zasebna linija rada u kodu, da se mogu praviti promjene bez diranja glavne verzije.","also":["branchevi","branches"]},{"id":"commit","g":"build","word":"Commit","text":"Sačuvan snimak koda, s kratkom bilješkom šta se promijenilo. Uvijek se možeš vratiti na njega.","also":["commitovi","commits"]},{"id":"push","g":"build","word":"Push","text":"Slanje sačuvanih snimaka (commitova) s ovog računara na zajedničku kopiju na internetu, kao GitHub, da budu sigurnosno kopirani i da ih drugi mogu dobiti."},{"id":"merge","g":"build","word":"Merge","text":"Spajanje izmjena iz jedne grane u drugu, obično nazad u glavnu verziju."},{"id":"pr","g":"build","word":"Pull request","text":"Traženje da se izmjene jedne grane provjere i spoje u glavnu verziju. Neke stranice to zovu merge request.","also":["PR","PRs","merge request","pull request"]},{"id":"refactor","g":"build","word":"Refaktorisanje","text":"Sređivanje koda bez mijenjanja onoga što radi: manje datoteke, jasnija imena, manje ponavljanja."},{"id":"bug","g":"build","word":"Bug","text":"Nešto što ne radi kako treba.","also":["bugovi","bugs"]},{"id":"peerreview","g":"build","word":"Recenzija kolega","text":"Drugi par očiju: neko osim autora provjerava rad prije nego što stigne do tebe, pa manje grešaka prođe. U AI-gileu svaku karticu provjerava drugi AI.","also":["pregled koda","peer review","code review"]},{"id":"code","g":"build","word":"Kod","text":"Napisane upute koje kažu računaru šta da radi. Zove se i izvorni kod.","also":["source code","izvorni kod"],"noTip":1},{"id":"proglang","g":"build","word":"Programski jezik","text":"Jezik za pisanje koda, kao JavaScript, Python ili Java. Različiti odgovaraju različitim poslovima.","also":["programming languages"]},{"id":"developer","g":"build","word":"Developer (programer)","text":"Neko ko piše i mijenja kod. Zove se i programer ili softverski inženjer.","also":["developer","developers","programmer","programmers","programeri","software engineer"]},{"id":"software","g":"build","word":"Softver","text":"Programi koji rade na računarima i telefonima, za razliku od samih uređaja (hardvera).","noTip":1},{"id":"app","g":"build","word":"Aplikacija","text":"Skraćeno od application: program koji ljudi koriste da nešto urade, na telefonu, računaru ili u web pregledniku.","also":["apps","app","application","applications","aplikacije"],"noTip":1},{"id":"webapp","g":"build","word":"Web aplikacija","text":"Aplikacija koja radi u web pregledniku, pa ništa ne treba instalirati.","also":["web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"Dio aplikacije koji vidiš i na koji klikćeš: ekrani, dugmad i riječi, često u tvom pregledniku.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"Pozadinski dio aplikacije koji čuva podatke i obavlja posao kad nešto klikneš, npr. provjera tvoje lozinke.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Rad i na front endu i na back endu.","also":["full-stack"]},{"id":"ui","g":"build","word":"Korisnički interfejs (UI)","text":"Ono što osoba vidi i koristi na ekranu: raspored, dugmad, meniji i tekst.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"Korisničko iskustvo (UX)","text":"Kakav je osjećaj koristiti nešto: lako, jasno i ugodno, ili zbunjujuće i sporo.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Pristupačnost (a11y)","text":"Pravljenje stvari koje svako može koristiti, uključujući ljude koji slabo vide, ne mogu koristiti miš ili koriste čitač ekrana.","also":["a11y","accessibility","pristupačnost"]},{"id":"responsive","g":"build","word":"Responzivni dizajn","text":"Pravljenje stranica koje se prilagođavaju i dobro rade na ekranu bilo koje veličine, od telefona do velikog monitora.","also":["responsive design"]},{"id":"designsys","g":"build","word":"Dizajn sistem","text":"Zajednički komplet boja, fontova, dugmadi i pravila, da svaki ekran izgleda i radi na isti način.","also":["design system","design systems"]},{"id":"architecture","g":"build","word":"Arhitektura","text":"Cjelokupni oblik sistema: koji su glavni dijelovi i kako međusobno razgovaraju."},{"id":"database","g":"build","word":"Baza podataka (DB)","text":"Organizovano skladište informacija, kao vrlo moćna tabela koju aplikacija može čitati i mijenjati.","also":["database","databases","DB","baza podataka"]},{"id":"schema","g":"build","word":"Šema baze podataka","text":"Raspored baze podataka: koje tabele s informacijama ima i šta ide u koju.","also":["schema","database schema"]},{"id":"sql","g":"build","word":"SQL","text":"Skraćeno od structured query language: jezik kojim se od mnogih baza podataka traže informacije ili se one mijenjaju.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Podaci","text":"Informacije koje čuva računar, kao imena, narudžbe ili postavke.","also":["data","dataset","datasets","skup podataka"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"Računar koji je stalno uključen i odgovara na zahtjeve drugih računara, npr. šalje web stranicu kad je posjetiš.","also":["servers"]},{"id":"client","g":"build","word":"Klijent","text":"Strana koja nešto traži, obično tvoj preglednik ili aplikacija, a razgovara sa serverom. U poslu to znači i jednostavno kupac.","also":["client","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Skraćeno od application programming interface: unaprijed određen jelovnik zahtjeva koje jedan program može uputiti drugom, npr. traženje današnje prognoze od vremenske službe.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"Jedna stavka na jelovniku API-ja: web adresa koju program može pozvati da nešto dobije ili pošalje.","also":["endpoints","krajnja tačka"]},{"id":"integration","g":"build","word":"Integracija","text":"Povezivanje dva sistema da rade zajedno, npr. tvoja prodavnica šalje narudžbe tvom računovodstvenom softveru.","also":["integration","integrations","integracije"]},{"id":"webhook","g":"build","word":"Webhook","text":"Poruka koju jedan sistem sam pošalje drugom u trenutku kad se nešto desi, npr. „uplata primljena“.","also":["webhooks"]},{"id":"library","g":"build","word":"Biblioteka (library)","text":"Gotov kod koji je neko drugi napisao, a ti ga možeš ponovo koristiti umjesto da ga pišeš od nule.","also":["library","libraries","biblioteke"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"Gotova struktura za pravljenje aplikacije koja određuje velik dio rasporeda koda, kao kostur kuće koji ti popunjavaš.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Razvojni komplet (SDK)","text":"Kutija alata, koda i primjera za pravljenje softvera za jednu platformu ili uslugu.","also":["SDK","SDKs","software development kit"]},{"id":"softdep","g":"build","word":"Softverska zavisnost","text":"Biblioteka ili alat koji tvom kodu treba da bi radio. Važno je držati ih ažurnim zbog sigurnosti.","also":["software dependency","software dependencies"]},{"id":"package","g":"build","word":"Paket","text":"Skup gotovog koda koji možeš instalirati i koristiti u projektu.","also":["package","packages","paketi"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Upravljač paketa","text":"Alat koji preuzima i ažurira pakete o kojima tvoj kod zavisi. npm je čest primjer.","also":["package manager","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"Najčešće korišten alat za čuvanje historije izmjena koda, u obliku commitova i grana."},{"id":"github","g":"build","word":"GitHub","text":"Web stranica koja drži Git repozitorije na internetu, da timovi mogu dijeliti kod, pregledati izmjene i pratiti posao."},{"id":"vcs","g":"build","word":"Kontrola verzija","text":"Čuvanje pune historije svake izmjene datoteka, da vidiš ko je šta promijenio i da se po potrebi vratiš. Git to radi.","also":["version control","source control","version control system"]},{"id":"clone","g":"build","word":"Clone (kloniranje)","text":"Pravljenje vlastite pune kopije repozitorija, s historijom, na tvom računaru.","also":["clone","cloned","cloning","klonirati"]},{"id":"pull","g":"build","word":"Pull","text":"Preuzimanje najnovijih commitova iz zajedničke kopije (kao što je GitHub) na tvoj računar. Suprotno od push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Glavna grana (main)","text":"Službena verzija koda od koje svi polaze, često zvana main ili master.","also":["main branch","master branch","master"]},{"id":"conflict","g":"build","word":"Merge konflikt","text":"Kad dvije izmjene diraju iste linije na različite načine, pa ih računar ne može spojiti i osoba mora izabrati.","also":["merge conflict","merge conflicts","konflikt spajanja"]},{"id":"diff","g":"build","word":"Diff","text":"Prikaz koji tačno pokazuje šta se promijenilo između dvije verzije: dodane i uklonjene linije.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Tvoja vlastita kopija tuđeg repozitorija, koju možeš mijenjati a da ne utičeš na original.","also":["forks","forked"]},{"id":"script","g":"build","word":"Skripta","text":"Kratak program koji sam obavlja jedan posao, npr. sređuje datoteke ili pokreće aplikaciju.","also":["script","scripts","skripte"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Pretvaranje koda u nešto spremno za pokretanje, ili sam rezultat spreman za pokretanje.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Kompajliranje","text":"Prevođenje koda koji su ljudi napisali u oblik koji računar može direktno izvršiti.","also":["compile","compiler","kompajler"]},{"id":"cli","g":"build","word":"Komandna linija (CLI)","text":"Tekstualni prozor u koji kucaš naredbe računaru umjesto da klikćeš. Zove se i terminal.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Konfiguracija (config)","text":"Postavke koje određuju kako se softver ponaša, držane odvojeno od koda da se lako mijenjaju.","also":["config","configuration","konfiguracija"],"noTip":1},{"id":"envvar","g":"build","word":"Varijabla okruženja","text":"Postavka koja se programu preda pri pokretanju, često za adrese ili lozinke da ne budu upisane u kod.","also":["environment variable","environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugiranje","text":"Traženje razloga zašto nešto ne radi i popravljanje toga.","also":["debugging","debug","debugged","otklanjanje grešaka"]},{"id":"pairing","g":"build","word":"Programiranje u paru","text":"Dvoje ljudi (ili osoba i AI) rade zajedno na istom kodu, jedno kuca a drugo provjerava.","also":["pair programming","pairing"]},{"id":"docs","g":"build","word":"Dokumentacija (docs)","text":"Napisana objašnjenja kako nešto radi ili kako se koristi.","also":["documentation","docs","dokumentacija"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Prva datoteka koju treba pročitati u repozitoriju: šta je projekat i kako ga pokrenuti.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Naslijeđeni sistem (legacy)","text":"Stariji sistem koji se još koristi, a težak je za mijenjanje, često jer ga malo ljudi još razumije.","also":["legacy system","legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Tehnički dug","text":"Prečice koje sada štede vrijeme, a kasnije izmjene čine sporijim, kao zajam na koji se skuplja kamata. Refaktorisanje ga otplaćuje.","also":["technical debt","tech debt"]},{"id":"test","g":"test","word":"Test","text":"Provjera da nešto radi kako treba. Neke testove računar sam pokreće svaki put kad se kod promijeni; druge su tvoje isprobavanje gotove kartice prije nego što je prihvatiš.","also":["testovi","tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Skraćeno od quality assurance (osiguranje kvaliteta): sve što se radi da bi posao bio ispravan prije objave. U AI-gileu to znači automatske provjere: kad je QA crven, nešto nije prošlo i ne može ići uživo dok se to ne popravi.","also":["provjere kvaliteta","osiguranje kvaliteta","quality checks"]},{"id":"testpile","g":"test","word":"Gomila testova","text":"Završene kartice koje čekaju da ih isprobaš, jedna za drugom. Prihvati jednu ili je vrati s bilješkom, i dolazi sljedeća.","also":["gomile testova","test pile"]},{"id":"autotest","g":"test","word":"Automatski test","text":"Provjera koju računar sam pokreće svaki put kad se kod promijeni, da se greške uhvate rano.","also":["automated test","automated tests","automatic tests","automatizovani test"]},{"id":"manualtest","g":"test","word":"Ručni test","text":"Osoba ručno isprobava urađeno da vidi ponaša li se kako treba.","also":["manual test","manual tests","manual testing","ručno testiranje"]},{"id":"unittest","g":"test","word":"Unit test","text":"Mala automatska provjera jednog sićušnog dijela koda, odvojeno od ostatka.","also":["unit tests","jedinični test"]},{"id":"integtest","g":"test","word":"Integracijski test","text":"Provjera da nekoliko dijelova ispravno radi zajedno, a ne samo jedan po jedan.","also":["integration test","integration tests"]},{"id":"endtoend","g":"test","word":"End-to-end test (E2E)","text":"Test koji se ponaša kao pravi korisnik od početka do kraja, npr. registracija, kupovina i plaćanje.","also":["E2E","end-to-end tests"]},{"id":"uat","g":"test","word":"Korisničko testiranje prihvatanja (UAT)","text":"Ljudi koji su tražili posao sami ga isprobaju i kažu radi li ono što im treba. Gomila testova u AI-gileu je njegova verzija toga.","also":["UAT","user acceptance testing","acceptance testing"]},{"id":"regression","g":"test","word":"Regresija","text":"Nešto što je ranije radilo, a pokvarilo se nakon izmjene. Regresijski testovi provjeravaju da stare stvari još rade.","also":["regression","regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test","text":"Vrlo brza provjera da glavne stvari uopšte rade, npr. odmah nakon što izmjena krene uživo. Ako ne prođe, stani i pogledaj.","also":["smoke tests"]},{"id":"exploratory","g":"test","word":"Istraživačko testiranje","text":"Slobodno isprobavanje proizvoda i bockanje na različite načine, da se nađu problemi koje planirane provjere promaše.","also":["exploratory testing","exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Test slučaj","text":"Jedan napisan scenarij za isprobavanje: koraci i šta bi se trebalo desiti.","also":["test case","test cases","testni slučaj"]},{"id":"coverage","g":"test","word":"Pokrivenost testovima","text":"Koliko je koda provjereno automatskim testovima. Više je obično sigurnije, ali visoka pokrivenost sama ne dokazuje da sve dobro radi.","also":["test coverage","code coverage","pokrivenost koda"]},{"id":"testdata","g":"test","word":"Testni podaci","text":"Izmišljeni primjeri podataka koji se koriste pri testiranju, da se ne otkriju privatni podaci stvarnih osoba.","also":["test data","test fixtures"]},{"id":"edgecase","g":"test","word":"Rubni slučaj","text":"Neobična situacija na granicama, npr. prazan obrazac ili ime s apostrofom, gdje se stvari često pokvare.","also":["edge case","edge cases","rubni slučajevi"]},{"id":"happypath","g":"test","word":"Srećna putanja (happy path)","text":"Uobičajen put u kojem sve ide kako treba. Dobro testiranje isprobava i nesrećne putanje."},{"id":"perftest","g":"test","word":"Testiranje performansi","text":"Provjera koliko je nešto brzo i kako se nosi s opterećenjem.","also":["performance testing","performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Testiranje opterećenja","text":"Provjera kako se sistem nosi kad ga koristi mnogo ljudi istovremeno.","also":["load testing","load test","load tests"]},{"id":"sectest","g":"test","word":"Sigurnosno testiranje","text":"Traženje slabosti koje bi nekome omogućile zloupotrebu sistema ili uvid u ono što ne bi smio vidjeti.","also":["security testing","security test","security tests"]},{"id":"accesstest","g":"test","word":"Testiranje pristupačnosti","text":"Provjera da proizvod mogu koristiti ljudi različitih sposobnosti, uključujući s čitačem ekrana ili samo tastaturom.","also":["accessibility testing","accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"Automatska provjera koja uočava vjerovatne greške i neuredan stil u kodu, kao provjera pravopisa za programe.","also":["linter","lint"]},{"id":"static","g":"test","word":"Statička analiza","text":"Provjera koda na probleme tako što se automatski čita, bez pokretanja.","also":["static analysis","static code analysis"]},{"id":"flaky","g":"test","word":"Nestabilan test (flaky)","text":"Test koji ponekad prođe a ponekad padne bez jasnog razloga, pa mu se ne može sasvim vjerovati.","also":["flaky test","flaky tests"]},{"id":"repro","g":"test","word":"Reprodukcija (repro)","text":"Namjerno ponovno izazivanje greške istim koracima, da se može proučiti i popraviti. Zapisivanje tih koraka je najkorisniji dio prijave greške.","also":["repro","reproduce","steps to reproduce","koraci za reprodukciju"]},{"id":"severity","g":"test","word":"Ozbiljnost","text":"Koliko je loš efekat problema, od sitne smetnje do zaustavljanja svega.","also":["severity","severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Kopiranje nove verzije softvera na računare koji ga pokreću, kao testna kopija ili usluga uživo."},{"id":"release","g":"change","word":"Izdanje","text":"Imenovan paket završenog posla koji zajedno ide u produkciju, s kratkim bilješkama o tome šta se promijenilo. 🚀 Izdanja pišu bilješke iz završenih kartica.","also":["izdanja","release"]},{"id":"rollback","g":"change","word":"Vraćanje unazad","text":"Vraćanje na zadnju verziju koja je radila kad nova pravi probleme. U AI-gileu Roll back skuplja korake poništavanja zapisane uz svaku izmjenu u jedan spisak.","also":["vrati unazad","rollback","roll back"]},{"id":"live","g":"change","word":"Produkcija","text":"Prava verzija koju ljudi koriste, za razliku od kopije za isprobavanje. Programeri kažu i production ili da je nešto „live“.","also":["uživo","production","live"],"noTip":1},{"id":"change","g":"change","word":"Promjena","text":"Planirana promjena nečega na šta se ljudi oslanjaju, prvo zapisana: šta, zašto, rizik, kada i kako je poništiti. Započni jednu sa 🔀 Podnesi promjenu.","also":["promjene","zahtjev za promjenu","change request"],"noTip":1},{"id":"risk","g":"change","word":"Rizik","text":"Nešto što bi moglo poći po zlu, ocijenjeno po tome koliko je vjerovatno i koliko bi bilo loše. ⚠️ Rizici ih drže na jednoj listi, s najvišom ocjenom prvo, svaki s datumom za ponovni pregled.","also":["rizici","registar rizika"]},{"id":"chgwin","g":"change","word":"Prozor za promjene","text":"Vrijeme kada promjene smiju u produkciju, recimo mirno utorak navečer. Izvan prozora kartica promjene ne može se završiti, osim ako je hitno.","also":["prozori za promjene","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Posljednja provjera tik prije objave izmjene: svaka osoba koja mora odobriti kaže Go ili No go. Ide dalje samo kad svi kažu Go.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Odobrenje","text":"Čekanje na „da“ prije nego što posao počne. Kartica koju podnese prijatelj, ili promjena, čeka u ✅ Odobrenja dok je ne odobriš ili odbiješ.","also":["odobrenja","approval"]},{"id":"quiettime","g":"change","word":"Mirno vrijeme","text":"Period, npr. tokom prenosa uživo, demonstracije ili preko noći, kad ništa ne ide uživo. Timovi nastavljaju raditi i testirati, ali objava čeka da završi. Drugdje se zove change freeze.","also":["mirna vremena","zamrzavanje promjena","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Način rada u kojem ljudi koji prave softver i ljudi koji ga pokreću rade kao jedan tim, uz mnogo automatizacije, pa izmjene idu uživo često i sigurno."},{"id":"cicd","g":"change","word":"CI/CD (kontinuirana integracija i isporuka)","text":"Izmjene svih se često spajaju u glavnu verziju i svaki put se automatski provjeravaju (kontinuirana integracija), pa je softver uvijek spreman za objavu jednim pritiskom na dugme (kontinuirana isporuka).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Kontinuirano postavljanje (continuous deployment)","text":"Korak dalje od kontinuirane isporuke: svaka izmjena koja prođe provjere sama ide uživo, bez dugmeta za pritisnuti.","also":["continuous deployment","continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline (cjevovod)","text":"Automatski niz koraka kroz koji izmjena prolazi na putu do objave, npr. build, test, pa deploy.","also":["pipeline","pipelines","cjevovod"]},{"id":"environment","g":"change","word":"Okruženje","text":"Jedna odvojena kopija sistema za jednu svrhu, npr. jedna za razvoj, jedna za testiranje i ona uživo.","also":["environment","environments","okruženja"],"noTip":1},{"id":"devenv","g":"change","word":"Razvojno okruženje","text":"Kopija u kojoj developer radi, često na svom računaru, gdje kvarenje stvari nikome ne šteti.","also":["development environment","dev environment"]},{"id":"testenv","g":"change","word":"Testno okruženje","text":"Odvojena kopija sistema koja služi samo za testiranje, da se prava usluga ne dira.","also":["test environment","test environments"]},{"id":"staging","g":"change","word":"Staging","text":"Posljednja kopija postavljena isto kao ona uživo, za završnu provjeru prije objave izmjene.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build artefakt","text":"Datoteka ili paket koji build proizvede, spreman za čuvanje, provjeru ili objavu.","also":["build artifact","build artifacts","artefakt"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"Hitna popravka puštena brzo, mimo uobičajenog plana, jer je nešto važno pokvareno.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Zakrpa (patch)","text":"Malo ažuriranje koje popravlja grešku ili zatvara sigurnosnu rupu. Brzo primjenjivanje sigurnosnih zakrpa je važno.","also":["patch","patches","security patch","security patches","sigurnosna zakrpa"]},{"id":"version","g":"change","word":"Broj verzije","text":"Oznaka poput 2.4.1 koja kaže koje izdanje imaš. Često se prvi broj mijenja za velike promjene, a zadnji za sitne popravke.","also":["version number","version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Bilješke o izdanju","text":"Kratak jednostavan spisak šta se promijenilo u izdanju, za one koji ga koriste, uključujući popravke i poznata ograničenja. Zove se i changelog.","also":["release notes","changelog","change log"]},{"id":"flag","g":"change","word":"Feature flag","text":"Prekidač za uključivanje i isključivanje funkcionalnosti, pa novi rad može ići uživo skriven i biti uključen (ili ponovo isključen) bez novog izdanja.","also":["feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Popravka lošeg izdanja brzim puštanjem nove, ispravljene verzije umjesto vraćanja na staru.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary izdanje","text":"Objava izmjene prvo za malu grupu, a za sve tek kad izgleda u redu. Naziv potiče od kanarinaca koje su rudari nosili pod zemlju kao rano upozorenje.","also":["canary release","canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green postavljanje","text":"Držanje dvije kopije sistema uživo i prebacivanje ljudi na novu odjednom, pa se može odmah vratiti ako krene po zlu.","also":["blue-green","blue-green deployment","blue green deployment"]},{"id":"zerodown","g":"change","word":"Postavljanje bez prekida (zero-downtime)","text":"Objava nove verzije a da usluga nikad ne stane za svoje korisnike.","also":["zero downtime","zero-downtime","zero-downtime deployment"]},{"id":"chgenable","g":"change","word":"Upravljanje promjenama","text":"Pomaganje da izmjene uspiju: vaganje rizika, dobijanje pravog odobrenja i odabir dobrog vremena. Zove se i change management.","also":["change enablement","change management"]},{"id":"cab","g":"change","word":"Odbor za promjene (CAB)","text":"Grupa koja pregleda važne izmjene i dogovara smiju li i kada ići dalje.","also":["CAB","change advisory board"]},{"id":"stdchange","g":"change","word":"Standardna promjena","text":"Promjena niskog rizika koja se svaki put radi na isti provjeren način, pa je unaprijed odobrena.","also":["standard change","standard changes"]},{"id":"normchange","g":"change","word":"Normalna promjena","text":"Promjena koju treba provjeriti i odobriti prije nego što krene.","also":["normal change","normal changes"]},{"id":"emergchange","g":"change","word":"Hitna promjena","text":"Promjena koja se mora desiti odmah da popravi ili spriječi ozbiljne probleme, s bržim odobrenjem u skladu s tim.","also":["emergency change","emergency changes"]},{"id":"automation","g":"change","word":"Automatizacija","text":"Prepuštanje računaru da sam obavlja posao koji se ponavlja, pa je brži i radi se uvijek na isti način.","also":["automation","automated","automatizovano"],"noTip":1},{"id":"infra","g":"change","word":"Infrastruktura","text":"Mašine, mreže i usluge na kojima softver radi.","also":["infrastructure","infra"]},{"id":"iac","g":"change","word":"Infrastruktura kao kod (IaC)","text":"Opisivanje servera i postavki u datotekama koje se čuvaju uz kod, pa se mogu ponovo napraviti potpuno isto svaki put.","also":["IaC","infrastructure as code"]},{"id":"cloud","g":"change","word":"Cloud (oblak)","text":"Iznajmljivanje računara, prostora i usluga od velikog pružaoca preko interneta, umjesto da posjeduješ vlastite mašine.","also":["cloud","the cloud","cloud computing","oblak"]},{"id":"provider","g":"change","word":"Cloud pružalac","text":"Kompanija koja iznajmljuje računarske resurse preko interneta, kao Amazon Web Services (AWS), Microsoft Azure ili Google Cloud.","also":["cloud provider","cloud providers","pružalac usluga u oblaku"]},{"id":"hosting","g":"change","word":"Hosting","text":"Mjesto gdje tvoja aplikacija ili web stranica živi i radi da ih ljudi mogu doseći, obično iznajmljeno od kompanije.","also":["hostovanje"]},{"id":"domain","g":"change","word":"Ime domene","text":"Web adresa koju ljudi ukucaju, kao example.com. Iznajmljuje se na godinu, pa se mora obnoviti.","also":["domain name","domain names","domain","domena"]},{"id":"dns","g":"change","word":"DNS","text":"Skraćeno od domain name system: adresar interneta koji ime poput example.com pretvara u adresu pravog računara.","also":["domain name system"]},{"id":"container","g":"change","word":"Kontejner","text":"Zatvoren paket s aplikacijom i svim što joj treba, pa radi isto na bilo kom računaru. Docker je najpoznatiji alat.","also":["container","containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtuelna mašina (VM)","text":"Zamišljen računar koji radi unutar pravog, pa jedna velika mašina može glumiti mnogo njih.","also":["VM","VMs","virtual machine","virtual machines","virtualna mašina"]},{"id":"serverless","g":"change","word":"Serverless","text":"Pokretanje koda bez brige o ikakvim serverima: pružalac ga pokreće kad treba, a ti plaćaš ono što iskoristiš."},{"id":"lb","g":"change","word":"Balanser opterećenja (load balancer)","text":"Nešto što raspoređuje posjetioce na nekoliko servera, da nijedan ne bude preopterećen.","also":["load balancer","load balancers"]},{"id":"cache","g":"change","word":"Keš (cache)","text":"Spremište nedavnih rezultata nadohvat ruke, da se isto ne mora ponovo preuzimati ili računati. Njegovo brisanje može popraviti stranice koje izgledaju zastarjelo.","also":["cache","caches","caching","cached","keširanje"]},{"id":"cdn","g":"change","word":"Mreža za isporuku sadržaja (CDN)","text":"Svjetski skup servera s kopijama tvojih stranica i slika blizu posjetilaca, da se brzo učitavaju.","also":["CDN","content delivery network"]},{"id":"migration","g":"change","word":"Migracija","text":"Prebacivanje podataka ili sistema sa stare postavke na novu, ili pažljiva promjena rasporeda baze podataka.","also":["migration","migrations","database migration"]},{"id":"service","g":"run","word":"Servis","text":"Nešto što si napravio i na šta se ljudi oslanjaju, poput web stranice ili aplikacije, o čemu se brine da nastavi raditi. Označi „Ovaj projekat je servis“ i reci šta nudi, ko ga koristi i ko je dežuran.","also":["servisi","usluga","service"]},{"id":"uptimepct","g":"run","word":"Uptime (vrijeme rada)","text":"Koliko vremena usluga radi, obično kao postotak. I 99,9% dopušta oko 43 minute prekida mjesečno.","also":["uptime percentage","postotak dostupnosti"]},{"id":"uptime","g":"run","word":"Provjera dostupnosti","text":"Automatska provjera, svakih nekoliko minuta, da tvoj servis još odgovara. Ako ne uspije nekoliko puta zaredom, AI-gile sam otvara karticu incidenta.","also":["uptime checks","provjere dostupnosti"]},{"id":"statuspage","g":"run","word":"Stranica statusa","text":"Javna stranica koja pokazuje radi li servis (zeleno, narandžasto ili crveno) s najnovijom viješću, da ljudi koji ga koriste mogu provjeriti umjesto da pitaju.","also":["stranice statusa","status page"]},{"id":"desk","g":"run","word":"Servisni pult","text":"Mjesto gdje stižu pitanja i prijave ljudi koji koriste tvoj servis. AI-gile svaku razvrsta kao zahtjev, incident ili ideju, i kaže ako liči na nešto što je već prijavljeno.","also":["servisni pultovi","pult za pomoć","podrška"]},{"id":"svcrequest","g":"run","word":"Servisni zahtjev","text":"Neko traži nešto uobičajeno, kao novi račun ili malo pomoći, umjesto da prijavljuje da je nešto pokvareno. Čeka svoj red; incident ide prvi.","also":["servisni zahtjevi"]},{"id":"incident","g":"run","word":"Incident","text":"Nešto što je pokvareno ili ne radi kako treba za ljude koji ga trenutno koriste, npr. web stranica ne radi ili je vrlo spora. Kartica incidenta 🔥 preskače red: prvo se vraća u rad.","also":["incidenti","incidencija"]},{"id":"major","g":"run","word":"Veliki incident","text":"Veliki incident: pogođeno mnogo ljudi, ili su novac ili podaci u opasnosti. Jedno dugme stavlja sve timove na njega (roj), budi onoga ko je dežuran i traži novost o stanju svakih 30 minuta.","also":["veliki incidenti","velika incidencija","major incident"]},{"id":"oncall","g":"run","word":"Dežurstvo","text":"Biti onaj ko se javlja kad se nešto pokvari, čak i noću. Svaki servis ima dežurnog člana tima kojeg prvog bude za njegove incidente.","also":["dežuran","na dežurstvu","on call","on-call"]},{"id":"replyby","g":"run","word":"Vrijeme za odgovor","text":"Koliko dugo kartica smije čekati prvi odgovor, recimo sat za incident. Nakon toga dobije crveni sat, da ništa ne bude tiho zaboravljeno. Zove se i cilj odgovora.","also":["vremena za odgovor","cilj odgovora","response target"]},{"id":"postmortem","g":"run","word":"Analiza nakon incidenta","text":"Kratak osvrt nakon incidenta: šta se desilo, šta je pomoglo i šta promijeniti, bez okrivljavanja ikoga. Incident se ne može zatvoriti bez nje.","also":["post-mortem","postmortem","revizija nakon incidenta"]},{"id":"problem","g":"run","word":"Problem","text":"Skriveni uzrok iza jednog ili više incidenata. Kartica 🧩 problema grupiše incidente koji se stalno vraćaju, da se uzrok pronađe i zauvijek popravi.","also":["problemi"],"noTip":1},{"id":"rootcause","g":"run","word":"Osnovni uzrok","text":"Pravi razlog zašto se nešto pokvarilo, a ne samo ono što si vidio da ne valja. Popravi osnovni uzrok i incident se prestaje vraćati.","also":["osnovni uzroci","root cause"]},{"id":"workaround","g":"run","word":"Privremeno rješenje","text":"Način da stvari rade dok pravo rješenje ne bude spremno, recimo ponovno pokretanje nečega kad zapne. Zapisuje se na kartici problema da niko ne mora ponovo smišljati.","also":["privremena rješenja","workaround"]},{"id":"knownerror","g":"run","word":"Poznata greška","text":"Problem čiji je uzrok shvaćen, ali još nije popravljen, obično uz zapisano privremeno rješenje. 🧩 Poznate greške ih navodi, pa svi koriste privremeno rješenje umjesto da ponovo kopaju.","also":["poznate greške","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Uputstva korak po korak za popravljanje poznate vrste problema, da se svaki put uradi isto i brzo. Nakon velikog incidenta tim ti može predložiti jedan da ga odobriš.","also":["runbookovi","priručnik"]},{"id":"ci","g":"run","word":"Konfiguraciona stavka","text":"Jedna stvar od koje tvoj servis zavisi, kao server, domen, certifikat, ključ ili dobavljač. 🗂️ Konfiguracione stavke ih prikazuje po servisu, pa vidiš na šta incident utiče i šta treba obnoviti ili napraviti sigurnosnu kopiju.","also":["konfiguracione stavke"]},{"id":"expiry","g":"run","word":"Datum isteka","text":"Datum kad nešto prestaje raditi ako se ne obnovi, kao sigurnosni certifikat web stranice ili njena web adresa. AI-gile prati te datume i 30 dana ranije pravi po jednu karticu za obnovu, da ništa ne stane iznenada.","also":["datumi isteka","istek","praćenje isteka"]},{"id":"backup","g":"run","word":"Sigurnosna kopija","text":"Sačuvana kopija tvojih podataka od ranije, na koju se možeš osloniti ako se nešto izgubi ili ošteti. AI-gile svaki dan pravi sigurnosnu kopiju tvojih ploča.","also":["sigurnosne kopije","bekap","backup"]},{"id":"restore","g":"run","word":"Vraćanje","text":"Vraćanje podataka iz sigurnosne kopije. Sigurnosna kopija se zaista računa tek kad znaš da se može vratiti, pa je vrijedi isprobati s vremena na vrijeme.","also":["vraćanje podataka","vraćeno","restore"]},{"id":"svcreview","g":"run","word":"Pregled servisa","text":"Pogled unazad na jedan mjesec servisa: otvoreni i riješeni incidenti, koliko su brzo ljudi dobili odgovor, dostupnost i potrošeni tokeni. Mjesečni pregled to prikazuje za svaki servis.","also":["pregledi servisa","mjesečni pregled","mjesečni pregledi"]},{"id":"accessreview","g":"run","word":"Pregled pristupa","text":"Provjera svakih 90 dana ko još može ući: linkovi za dijeljenje, uloge prijatelja te sačuvane lozinke i ključevi. Svaki zadržavaš ili uklanjaš, da stari pristup ne ostane.","also":["pregledi pristupa"]},{"id":"improvements","g":"run","word":"Lista poboljšanja","text":"Sve u čemu je tim odlučio postati bolji, na jednom mjestu: prijedlozi s retra, akcije iz revizija i popravke problema, svaka sa svojim statusom. Nađi je pod 📈 Poboljšanja.","also":["liste poboljšanja","poboljšanja"]},{"id":"tokencap","g":"run","word":"Limit tokena","text":"Mjesečni limit tokena koje agenti jednog servisa smiju potrošiti. Na 80% dobiješ upozorenje; na 100% njihov rad u pozadini čeka do sljedećeg mjeseca ili dok ne povećaš limit.","also":["limiti tokena"]},{"id":"svcmgmt","g":"run","word":"Upravljanje uslugama","text":"Sve što je potrebno da usluga ostane korisna i ispravna za ljude koji se na nju oslanjaju, iz dana u dan.","also":["service management"]},{"id":"itil","g":"run","word":"ITIL","text":"Široko korišten vodič za dobro upravljanje uslugama, koji pokriva stvari kao incidenti, problemi i promjene. Naziv je nekad značio IT Infrastructure Library."},{"id":"itsm","g":"run","word":"Upravljanje IT uslugama (ITSM)","text":"Vođenje tehnologije kao usluge za ljude, s jasnim načinima za rješavanje zahtjeva, incidenata, promjena i poboljšanja.","also":["ITSM","IT service management"]},{"id":"managed","g":"run","word":"Upravljana usluga","text":"Usluga koju neko drugi vodi i održava za tebe, prema dogovoru o tome koliko dobro mora raditi.","also":["managed service","managed services"]},{"id":"svcowner","g":"run","word":"Vlasnik usluge","text":"Osoba koja odgovara za uslugu u cjelini: koliko dobro radi, koliko košta i kako se poboljšava.","also":["service owner","service owners"]},{"id":"sla","g":"run","word":"Ugovor o nivou usluge (SLA)","text":"Pisano obećanje klijentima o tome koliko će dobro usluga raditi, npr. „dostupna 99,9% vremena“ ili „odgovor u roku sata“, često uz povrat novca ako se prekrši.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Cilj nivoa usluge (SLO)","text":"Vlastiti cilj tima o tome koliko dobro usluga treba raditi u nekom periodu, obično malo stroži od SLA radi sigurnosti.","also":["SLO","SLOs","service level objective"]},{"id":"sli","g":"run","word":"Pokazatelj nivoa usluge (SLI)","text":"Stvarno mjerenje koje provjeravaš u odnosu na cilj, npr. udio posjeta koje su se uredno učitale.","also":["SLI","SLIs","service level indicator"]},{"id":"availability","g":"run","word":"Dostupnost","text":"Mogu li ljudi koristiti uslugu kad im treba, često mjereno kao uptime.","also":["availability","high availability","visoka dostupnost"]},{"id":"downtime","g":"run","word":"Zastoj (downtime)","text":"Vrijeme kad usluga ne radi ili je isključena, planirano ili ne.","also":["downtime","down time"]},{"id":"errorbudget","g":"run","word":"Budžet grešaka (error budget)","text":"Mala količina kvarova koju dopušta tvoj cilj pouzdanosti. Dok nešto ostaje, možeš rizikovati s izmjenama; kad se potroši, usporavaš.","also":["error budget","error budgets"]},{"id":"outage","g":"run","word":"Ispad (outage)","text":"Vrijeme kad je usluga nedostupna ili jako pokvarena za svoje korisnike.","also":["outage","outages"]},{"id":"degraded","g":"run","word":"Degradirano","text":"Radi, ali loše: sporo, ili neki dijelovi ne rade.","also":["degraded","degraded service"]},{"id":"monitoring","g":"run","word":"Nadzor (monitoring)","text":"Automatsko stalno posmatranje usluge, da se problemi uoče, idealno prije nego što ih korisnici primijete.","also":["monitoring"]},{"id":"observability","g":"run","word":"Opservabilnost (observability)","text":"Koliko dobro možeš izvana reći šta se događa unutar sistema, pomoću njegovih logova, brojeva i tragova.","also":["observability","o11y"]},{"id":"log","g":"run","word":"Log","text":"Dnevnik koji program vodi o tome šta radi, a koristi se da se utvrdi šta je pošlo po zlu.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trag (trace)","text":"Zapis kako jedan zahtjev putuje kroz različite dijelove sistema, korak po korak, pokazujući gdje je usporio.","also":["trace","traces","tracing"]},{"id":"latency","g":"run","word":"Latencija","text":"Koliko vremena treba da nešto odgovori, npr. čekanje između klika i pojave stranice.","also":["latency"]},{"id":"alert","g":"run","word":"Upozorenje (alert)","text":"Automatska poruka da nešto traži pažnju, npr. da web stranica ne odgovara.","also":["alert","alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Zasićenost upozorenjima (alert fatigue)","text":"Kad ima toliko upozorenja da ih ljudi počnu ignorisati, uključujući i ona važna.","also":["alert fatigue","alarm fatigue"]},{"id":"dashboard","g":"run","word":"Kontrolna ploča (dashboard)","text":"Ekran koji na prvi pogled pokazuje najvažnije brojeve i stanja.","also":["dashboard","dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Paging (hitno javljanje)","text":"Hitno zvanje ili buđenje dežurne osobe zbog problema.","also":["paging","paged"]},{"id":"escalation","g":"run","word":"Eskalacija","text":"Uključivanje nekoga s više znanja ili ovlasti kad se problem ne može riješiti na trenutnom nivou, ili ne dovoljno brzo.","also":["escalation","escalate","escalated","eskalirati"]},{"id":"triage","g":"run","word":"Trijaža","text":"Brzo razvrstavanje pristiglih problema po hitnosti i važnosti, da se najgore riješi prvo.","also":["triage","triaged"]},{"id":"impact","g":"run","word":"Uticaj (impact)","text":"Koliko nešto utiče na ljude: na koliko njih i koliko jako.","noTip":1},{"id":"urgency","g":"run","word":"Hitnost","text":"Koliko brzo se nešto mora riješiti. Uticaj i hitnost zajedno određuju prioritet.","noTip":1},{"id":"plevels","g":"run","word":"Nivoi prioriteta (P1, P2…)","text":"Oznake koliko je problem hitan. P1 je najozbiljniji i traži hitnu akciju.","also":["P1","P2","P3","P4","priority levels"]},{"id":"queue","g":"run","word":"Red tiketa","text":"Spisak zahtjeva i incidenata koji čekaju da ih neko preuzme.","also":["ticket queue","ticket queues"]},{"id":"tiers","g":"run","word":"Prva i druga linija","text":"Nivoi podrške: prva linija prima poziv i rješava jednostavne stvari; druga ima dublja znanja za teže. Zovu se i tier 1 i tier 2.","also":["first-line support","tier 1","tier 2","prva linija","druga linija"]},{"id":"ic","g":"run","word":"Komandant incidenta","text":"Jedna osoba koja vodi odgovor na incident, da svi znaju ko odlučuje i ko šta radi.","also":["incident commander","incident commanders"]},{"id":"responsetime","g":"run","word":"Vrijeme odziva","text":"Koliko prođe prije nego što neko prvi put preuzme zahtjev ili incident.","also":["response time","response times"]},{"id":"resolution","g":"run","word":"Vrijeme rješavanja","text":"Koliko traje potpuno rješavanje zahtjeva ili incidenta, od prijave do popravke.","also":["resolution time","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Prosječno vrijeme oporavka (MTTR)","text":"U prosjeku, koliko traje da usluga ponovo proradi nakon kvara. MTTR može značiti malo različite stvari, pa reci šta mjeriš.","also":["MTTR","mean time to recover","mean time to restore"]},{"id":"mtbf","g":"run","word":"Prosječno vrijeme između kvarova (MTBF)","text":"U prosjeku, koliko usluga radi prije nego što se nešto pokvari.","also":["MTBF","mean time between failures"]},{"id":"cmdb","g":"run","word":"Baza konfiguracijskih stavki (CMDB)","text":"Spisak svih tvojih konfiguracijskih stavki i kako su povezane, da vidiš šta od čega zavisi.","also":["CMDB","configuration management database"]},{"id":"asset","g":"run","word":"Imovina (asset)","text":"Sve vrijedno što posjeduješ ili plaćaš da bi usluga radila, npr. laptop, softverska licenca ili domena.","also":["asset","assets"],"noTip":1},{"id":"capplan","g":"run","word":"Planiranje kapaciteta","text":"Osiguravanje da će biti dovoljno računarske snage, prostora i ljudi za ono što dolazi.","also":["capacity planning","capacity plan"]},{"id":"scaling","g":"run","word":"Skaliranje","text":"Nošenje s većim brojem korisnika davanjem mašini veće snage (scale up) ili dodavanjem više mašina (scale out).","also":["scaling","scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Kontinuitet poslovanja","text":"Planovi za održavanje važnih stvari u radu kad nešto veliko pođe po zlu, npr. gubitak kancelarije, ključnog dobavljača ili računara.","also":["business continuity","business continuity plan"]},{"id":"dr","g":"run","word":"Oporavak od katastrofe (DR)","text":"Plan i alati za vraćanje usluge nakon nečeg ozbiljnog, npr. gubitka cijelog data centra.","also":["DR","disaster recovery"]},{"id":"rto","g":"run","word":"Ciljno vrijeme oporavka (RTO)","text":"Najduže što usluga smije biti nedostupna nakon katastrofe prije nego što mora ponovo raditi.","also":["RTO","recovery time objective"]},{"id":"rpo","g":"run","word":"Ciljna tačka oporavka (RPO)","text":"Koliko nedavnih podataka možeš priuštiti da izgubiš, mjereno vremenom. RPO od jednog sata znači sigurnosne kopije bar svaki sat.","also":["RPO","recovery point objective"]},{"id":"redundancy","g":"run","word":"Redundancija","text":"Imati spremne rezerve, npr. drugi server, da jedan kvar ne zaustavi uslugu.","also":["redundancy"]},{"id":"failover","g":"run","word":"Failover","text":"Automatsko prebacivanje na rezervni sistem kad uobičajeni otkaže.","also":["fail over"]},{"id":"spof","g":"run","word":"Jedinstvena tačka otkaza","text":"Jedan dio koji sa sobom sruši sve kad se pokvari, jer nema rezerve.","also":["single point of failure","single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Prozor za održavanje","text":"Planirano vrijeme kad usluga može biti pauzirana ili spora zbog održavanja, o čemu se korisnici unaprijed obavijeste.","also":["maintenance window","maintenance windows","planned maintenance","planirano održavanje"]},{"id":"handover","g":"run","word":"Primopredaja (handover)","text":"Predavanje posla, znanja i odgovornosti drugoj osobi ili timu, da se ništa ne izgubi.","also":["handover","handovers"]},{"id":"kb","g":"run","word":"Baza znanja","text":"Zbirka članaka pomoći i odgovora, za korisnike i za tim.","also":["knowledge base","knowledge bases"]},{"id":"csat","g":"run","word":"Zadovoljstvo korisnika (CSAT)","text":"Ocjena korisnika koliko su bili zadovoljni, često se traži nakon što se zahtjev zatvori.","also":["CSAT","customer satisfaction"]},{"id":"supplier","g":"run","word":"Dobavljač","text":"Vanjska kompanija na koju se oslanjaš, npr. tvoj hosting provajder. Zove se i vendor ili treća strana.","also":["supplier","suppliers","vendor","vendors","third party","treća strana"],"noTip":1},{"id":"retire","g":"run","word":"Gašenje usluge","text":"Trajno i sigurno isključivanje usluge: obavještavanje korisnika, briga o njenim podacima i pristupu, i zaustavljanje troškova.","also":["service retirement","retiring a service"]},{"id":"eol","g":"run","word":"Kraj životnog vijeka (EOL)","text":"Kad proizvod prestane dobijati ažuriranja ili podršku od proizvođača, pa ga treba zamijeniti.","also":["EOL","end of life","end-of-life"]},{"id":"cybersec","g":"sec","word":"Sajber sigurnost","text":"Zaštita sistema i podataka od provale, krađe ili oštećenja.","also":["cybersecurity","cyber security"]},{"id":"authn","g":"sec","word":"Autentifikacija","text":"Provjera ko je neko, obično lozinkom ili kodom. Često skraćeno authn.","also":["authentication","authn"]},{"id":"authz","g":"sec","word":"Autorizacija","text":"Provjera šta neko smije raditi kad već znaš ko je. Često skraćeno authz.","also":["authorisation","authorization","authz"]},{"id":"mfa","g":"sec","word":"Višefaktorska autentifikacija (MFA)","text":"Prijava s dva ili više dokaza, npr. lozinka plus kod na telefonu. Zove se i dvofaktorska (2FA).","also":["MFA","2FA","two-factor","two-factor authentication","dvofaktorska autentifikacija"]},{"id":"sso","g":"sec","word":"Jedinstvena prijava (SSO)","text":"Jednom se prijaviš da uđeš u mnogo sistema, npr. korištenjem poslovnog računa svugdje.","also":["SSO","single sign-on"]},{"id":"pwmgr","g":"sec","word":"Upravljač lozinki","text":"Aplikacija koja pravi jake lozinke i pamti ih umjesto tebe.","also":["password manager","password managers"]},{"id":"secret","g":"sec","word":"Tajna (secret)","text":"Lozinka, ključ ili drugi privatni kod koji program koristi da uđe u nešto. Nikad se ne smije dijeliti niti upisivati u kod.","also":["secret","secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API ključ","text":"Tajni kod koji programu omogućava da koristi API druge usluge i pokazuje ko je koristi (i plaća).","also":["API key","API keys"]},{"id":"accesstoken","g":"sec","word":"Pristupni token","text":"Privremena propusnica koja dokazuje da program smije ući, pa mu svaki put ne treba tvoja lozinka. Nije isto što i AI token.","also":["access token","access tokens"]},{"id":"encryption","g":"sec","word":"Šifriranje","text":"Pretvaranje informacija u nečitljiv oblik tako da ih može pročitati samo neko s pravim ključem.","also":["encryption","encrypted","encrypt","enkripcija"]},{"id":"https","g":"sec","word":"HTTPS","text":"Siguran način na koji putuju web stranice, što pokazuje katanac u pregledniku, pa ih niko usput ne može čitati ni mijenjati."},{"id":"cert","g":"sec","word":"SSL/TLS certifikat","text":"Digitalna lična karta koja web stranici omogućava da dokaže ko je i koristi HTTPS. Ističe, pa se mora obnoviti.","also":["TLS certificate","SSL certificate","certificate","certificates","certifikat"]},{"id":"permissions","g":"sec","word":"Dozvole","text":"Pravila o tome ko šta smije vidjeti ili mijenjati.","also":["permission","permissions","ovlasti"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Najmanje privilegije","text":"Davanje svakoj osobi ili programu samo onog pristupa koji im zaista treba, i samo onoliko dugo koliko im treba.","also":["least privilege","principle of least privilege"]},{"id":"rbac","g":"sec","word":"Kontrola pristupa po ulogama (RBAC)","text":"Davanje pristupa po ulozi, kao gledalac ili urednik, umjesto osobu po osobu.","also":["RBAC","role-based access","role-based access control"]},{"id":"vuln","g":"sec","word":"Ranjivost","text":"Slabost koju bi neko mogao iskoristiti za provalu ili pravljenje štete.","also":["vulnerability","vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"Slabost za koju napadači znaju prije nego što su je proizvođači imali vremena popraviti.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Zlonamjerni softver (malware)","text":"Štetan softver, poput virusa, napravljen da oštećuje, špijunira ili krade.","also":["malware","zlonamjerni softver"]},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Zlonamjerni softver koji zaključa tvoje datoteke i traži novac da ih otključa. Dobre sigurnosne kopije su najbolja odbrana.","also":["ransomware attack","ucjenjivački softver"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Lažne poruke koje te pokušavaju prevariti da odaš lozinke ili novac, ili otvoriš nešto štetno.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Socijalni inženjering","text":"Prevara ljudi, a ne računara, da daju pristup, npr. lažan poziv „IT podrške“."},{"id":"firewall","g":"sec","word":"Firewall (vatrozid)","text":"Čuvar koji odlučuje koji mrežni saobraćaj smije ući ili izaći.","also":["firewalls","vatrozid"]},{"id":"vpn","g":"sec","word":"VPN","text":"Skraćeno od virtual private network: privatna, šifrovana veza preko interneta, često za sigurno povezivanje s poslovnim sistemima.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Napad uskraćivanjem usluge (DoS, DDoS)","text":"Zatrpavanje usluge tolikim lažnim saobraćajem da je pravi ljudi ne mogu koristiti. DDoS znači da dolazi s mnogo računara odjednom.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetracijski test (pen test)","text":"Angažovanje prijateljskih stručnjaka da pokušaju provaliti, da se slabosti nađu prije nego što ih nađu pravi napadači.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Sigurnosna revizija","text":"Pažljiva provjera koliko je nešto zaštićeno, prema spisku dobre prakse.","also":["security audit","security audits"]},{"id":"threatmodel","g":"sec","word":"Modeliranje prijetnji","text":"Promišljanje o tome ko bi mogao napasti nešto, kako, i šta uraditi da ga se zaustavi.","also":["threat modelling","threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Curenje podataka","text":"Kad privatne informacije dospiju do ljudi koji ih ne bi trebali imati, ili se izgube ili promijene bez dozvole.","also":["data breach","data breaches","povreda podataka"]},{"id":"pii","g":"sec","word":"Lični podaci","text":"Svaka informacija o osobi koja se može identifikovati, npr. ime, adresa e-pošte ili lokacija. Zovu se i PII.","also":["personal data","PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"Evropski zakon o ličnim podacima (Ujedinjeno Kraljevstvo ima svoju verziju): prikupljaj samo ono što ti treba, čuvaj to sigurno i dopusti ljudima da vide ili obrišu svoje.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Zaštita podataka","text":"Pravilna briga o ličnim podacima, u skladu sa zakonom.","also":["data protection","data protection law"]},{"id":"privacypolicy","g":"sec","word":"Politika privatnosti","text":"Javna stranica koja kaže koje lične podatke prikupljaš, zašto i šta s njima radiš.","also":["privacy policy","privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Saglasnost","text":"Jasno i slobodno „da“ osobe da se njeni podaci koriste na određen način. Može ga povući u bilo kom trenutku.","also":["consent","opt-in","pristanak"],"noTip":1},{"id":"cookie","g":"sec","word":"Kolačić (cookie)","text":"Mala datoteka koju web stranica sprema u tvom pregledniku da bi nešto zapamtila, npr. tvoju prijavu. Za neke je prvo potrebna tvoja saglasnost.","also":["cookie","cookies","kolačići"],"noTip":1},{"id":"minimisation","g":"sec","word":"Minimizacija podataka","text":"Prikupljanje i čuvanje samo onih ličnih podataka koji su zaista potrebni za posao.","also":["data minimisation","data minimization"]},{"id":"retention","g":"sec","word":"Rok čuvanja podataka","text":"Koliko se podaci čuvaju prije brisanja. Čuvati ih samo koliko treba je sigurnije i često propisano zakonom.","also":["data retention","retention period"]},{"id":"anon","g":"sec","word":"Anonimizacija","text":"Mijenjanje podataka tako da se iz njih više niko razumno ne može identifikovati.","also":["anonymisation","anonymised","anonymization","anonymous data","anonimizirano"]},{"id":"pseudo","g":"sec","word":"Pseudonimizacija","text":"Zamjena imena i drugih detalja šiframa, uz ključ držan odvojeno za njihovo povezivanje. I dalje su to lični podaci.","also":["pseudonymisation","pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Ugovor o obradi podataka (DPA)","text":"Ugovor koji kaže kako dobavljač smije postupati s ličnim podacima u tvoje ime.","also":["DPA","data processing agreement"]},{"id":"dpia","g":"sec","word":"Procjena uticaja na zaštitu podataka (DPIA)","text":"Pažljiv pogled, prije početka, na to kako bi plan korištenja ličnih podataka mogao uticati na ljude i kako smanjiti rizike.","also":["DPIA","data protection impact assessment"]},{"id":"auditlog","g":"sec","word":"Revizijski zapis (audit log)","text":"Zapis ko je šta radio i kada, da se radnje mogu kasnije provjeriti.","also":["audit log","audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Usklađenost (compliance)","text":"Poštovanje zakona, pravila i standarda koji se na tebe odnose, i mogućnost da to pokažeš.","also":["compliance","compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Poznat međunarodni standard za upravljanje sigurnošću informacija. Kompanije mogu dobiti certifikat prema njemu.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Američki izvještaj, koji provjeravaju vanjski revizori, a pokazuje da kompanija ispravno brine o podacima klijenata.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"AI koji sam radi na zadatku: čita kod, pravi izmjene, pokreće provjere i javlja se. Njegov rad se i dalje provjerava.","also":["agenti","agents"]},{"id":"token","g":"ai","word":"Token","text":"Mali komadi teksta koje AI čita i piše, svaki otprilike tri četvrtine riječi. Korištenje AI-ja se broji u tokenima, pa manje tokena ostavlja više tvog plana.","also":["tokeni","tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Mala naredba koja se sama pokreće u zadatom trenutku, npr. kad počne AI sesija, da tim čuje tvoje komentare.","also":["hookovi","hooks"]},{"id":"ai","g":"ai","word":"Vještačka inteligencija (AI)","text":"Računarski sistemi koji rade stvari za koje obično mislimo da trebaju čovjeka, kao pisanje, odgovaranje na pitanja ili prepoznavanje slika.","also":["AI","artificial intelligence","umjetna inteligencija"],"noTip":1},{"id":"ml","g":"ai","word":"Mašinsko učenje (ML)","text":"Način da računari nauče obrasce iz mnogo primjera, umjesto da im se daju tačna pravila.","also":["ML","machine learning"]},{"id":"model","g":"ai","word":"Model","text":"Obučeni „mozak“ AI sistema, nastao učenjem na ogromnom broju primjera. Modeli se razlikuju po sposobnosti, brzini i cijeni.","also":["models","AI model","AI modeli","modeli"],"noTip":1},{"id":"llm","g":"ai","word":"Veliki jezički model (LLM)","text":"AI model obučen na ogromnim količinama teksta, pa može čitati i pisati jezik.","also":["LLM","LLMs","large language model"]},{"id":"genai","g":"ai","word":"Generativni AI","text":"AI koji stvara nove stvari, poput teksta, slika ili koda, a ne samo da ih razvrstava ili prepoznaje.","also":["GenAI","generative AI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"Program s kojim razgovaraš običnim jezikom, kucanjem ili govorom.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt (upit)","text":"Ono što daješ AI-ju: tvoje pitanje ili upute, plus sve što mu predaš. Jasniji promptovi obično donose bolje odgovore.","also":["prompt","prompts","promptovi"]},{"id":"prompteng","g":"ai","word":"Prompt inženjering","text":"Vještina pisanja promptova koji daju pouzdane, korisne rezultate.","also":["prompt engineering"]},{"id":"sysprompt","g":"ai","word":"Sistemski prompt","text":"Pozadinske upute koje AI dobije prije početka razgovora, a određuju mu ulogu i pravila. Teže više od onoga što ti kucaš.","also":["system prompt","system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Kontekst","text":"Sve što AI vidi dok radi: upute, tvoje poruke, datoteke koje je pročitao i raniji odgovori.","noTip":1},{"id":"ctxwin","g":"ai","word":"Kontekstni prozor","text":"Koliko toga AI može držati na umu odjednom, mjereno u tokenima. Iza toga se stariji dijelovi odbacuju ili sažimaju.","also":["context window","context windows"]},{"id":"session","g":"ai","word":"Sesija","text":"Jedan radni razgovor s AI-jem, od početka do kraja. Nova sesija počinje sa svježom memorijom.","also":["session","sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Memorija","text":"Bilješke koje AI čuva između sesija, da pamti tvoje sklonosti i ranije odluke.","noTip":1},{"id":"hallucination","g":"ai","word":"Halucinacija","text":"Kad AI kaže nešto što zvuči samouvjereno, a izmišljeno je ili pogrešno. Provjeri važne činjenice.","also":["hallucination","hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Obuka (training)","text":"Učenje modela pokazivanjem ogromnog broja primjera, prije nego što ga iko koristi.","also":["training","trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Podaci za obuku","text":"Primjeri iz kojih je model učio. Njegovo znanje staje na datumu kad su ti podaci prikupljeni.","also":["training data","training set"]},{"id":"cutoff","g":"ai","word":"Granica znanja (knowledge cutoff)","text":"Datum na kojem završava AI-jevo ugrađeno znanje. Ne zna za kasnije stvari osim ako ih potraži.","also":["knowledge cutoff","training cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning (fino podešavanje)","text":"Dodatna obuka postojećeg modela na tvojim primjerima, da bude bolji u jednom određenom poslu.","also":["fine-tuning","fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inferencija","text":"Kad se AI model zaista koristi da nešto odgovori, za razliku od obuke.","also":["inference","model inference"]},{"id":"tooluse","g":"ai","word":"Korištenje alata (tool use)","text":"AI koji može nešto raditi, a ne samo pričati: pokretati naredbe, čitati datoteke ili pretraživati web, pomoću alata koje mu aplikacija daje.","also":["tool use","tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"Pomoćni AI kojem glavni AI daje manji posao, a od njega dobija rezultat.","also":["subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"Nekoliko AI-ja radi zajedno na jednom poslu, svaki sa svojim dijelom, kao mali tim.","also":["multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomija","text":"Koliko toga AI smije uraditi sam prije nego što mora pitati osobu.","also":["autonomy","autonomous"]},{"id":"hitl","g":"ai","word":"Čovjek u petlji (human in the loop)","text":"Osoba ostaje uključena i u ključnim trenucima provjerava ili odobrava ono što AI radi. U AI-gileu to si ti.","also":["human in the loop","human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Zaštitne ograde (guardrails)","text":"Ograničenja i provjere koji drže radnje AI-ja sigurnim, npr. odobrenje prije nego što bilo šta ode uživo. Smanjuju rizik od grešaka, ali ih ne isključuju.","also":["guardrails","guardrail"]},{"id":"rag","g":"ai","word":"Generisanje potpomognuto pretraživanjem (RAG)","text":"Dopuštanje AI-ju da prije odgovora potraži stvari u tvojim vlastitim dokumentima, pa njegovi odgovori počivaju na tvojim činjenicama.","also":["RAG","retrieval-augmented generation","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Pretvaranje teksta u listu brojeva koja hvata njegovo značenje, da računar može naći stvari slična značenja.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Vektorska baza podataka","text":"Baza podataka napravljena za pretragu tih lista brojeva (embeddinga), da nađe materijal sličnog značenja.","also":["vector database","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Uobičajen način za priključivanje alata i izvora podataka u AI aplikacije, da ih AI može koristiti.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperatura","text":"Postavka koja određuje koliko su odgovori AI-ja avanturistički. Niska daje postojanije, predvidljivije odgovore; visoka raznovrsnije. Nijedna ne znači da je uvijek u pravu.","also":["temperature","model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodalno","text":"Sposobno raditi s više od jedne vrste informacija, kao što su tekst, slike i zvuk.","also":["multimodal","multi-modal"]},{"id":"evals","g":"ai","word":"Evaluacija (eval)","text":"Planiran test koliko dobro AI radi na odabranim primjerima, da možeš porediti modele ili promptove.","also":["evaluation","eval","evals"]},{"id":"bias","g":"ai","word":"Pristrasnost (bias)","text":"Kad AI (ili osoba) nepravedno naginje na jednu stranu, često zbog onoga iz čega je učio.","also":["bias","biased","pristrasnost"],"noTip":1},{"id":"responsible","g":"ai","word":"Odgovoran AI","text":"Korištenje AI-ja pošteno, sigurno i iskreno, a da ljudi i dalje odgovaraju za rezultate.","also":["responsible AI","ethical AI","etički AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"Trik u kojem skrivene upute u web stranici ili datoteci pokušavaju natjerati AI da uradi nešto što njegov korisnik nije tražio.","also":["prompt injections"]},{"id":"ratelimit","g":"ai","word":"Ograničenje učestalosti (rate limit)","text":"Gornja granica koliko zahtjeva smiješ poslati usluzi u zadatom vremenu. Ako je pređeš, moraš čekati.","also":["rate limit","rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Ograničenje potrošnje","text":"Koliko AI posla tvoj plan dopušta u nekom periodu, nakon čega staje ili košta više.","also":["usage limit","usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Pravljenje softvera uglavnom tako što AI-ju opišeš šta želiš i pustiš ga da napiše kod.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budžet","text":"Iznos novca izdvojen za nešto.","also":["budget","budgets"],"noTip":1},{"id":"costest","g":"money","word":"Procjena troškova","text":"Najbolja pretpostavka koliko će nešto koštati prije početka.","also":["cost estimate","cost estimates"]},{"id":"roi","g":"money","word":"Povrat ulaganja (ROI)","text":"Šta dobiješ nazad u poređenju s onim što uložiš. Ako je pozitivan, isplati se.","also":["ROI","return on investment"]},{"id":"tco","g":"money","word":"Ukupni trošak vlasništva (TCO)","text":"Sve što nešto zaista košta tokom cijelog života, ne samo cijena kupovine: rad, podrška, nadogradnje i na kraju gašenje.","also":["TCO","total cost of ownership"]},{"id":"capex","g":"money","word":"CapEx i OpEx","text":"CapEx je novac potrošen unaprijed na stvari koje zadržavaš; OpEx je tekuća potrošnja, kao mjesečni računi.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Pretplata","text":"Redovno plaćanje, obično mjesečno ili godišnje, da nastaviš koristiti nešto.","also":["subscription","subscriptions","pretplate"],"noTip":1},{"id":"saas","g":"money","word":"Softver kao usluga (SaaS)","text":"Softver koji koristiš na internetu i plaćaš pretplatom, dok ga proizvođač vodi za tebe.","also":["SaaS","software as a service"]},{"id":"payg","g":"money","word":"Plaćanje po upotrebi","text":"Plaćanje samo onoga što koristiš, kao kod cloud računarstva ili AI tokena.","also":["pay as you go","pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Prekoračenje","text":"Korištenje iznad onoga što tvoj plan uključuje, što može koštati dodatno.","also":["overage","overages","overage charges"]},{"id":"billingalert","g":"money","word":"Upozorenje o naplati","text":"Poruka kad potrošnja ili korištenje dostigne nivo koji odabereš. Upozorava te, ali ne zaustavlja uvijek daljnje troškove.","also":["billing alert","billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Besplatni nivo","text":"Besplatan nivo plaćene usluge, s ograničenjima. Zgodan za početak.","also":["free tier","free plan","besplatni plan"]},{"id":"pricing","g":"money","word":"Cjenovni plan","text":"Različiti paketi koje usluga prodaje, svaki sa svojom cijenom i ograničenjima.","also":["pricing plan","pricing plans","price plan","cjenovni paket"]},{"id":"licence","g":"money","word":"Licenca","text":"Pravila o tome kako smiješ koristiti, kopirati, mijenjati ili dijeliti nešto što je neko drugi napravio, npr. softver, fontove ili slike.","also":["licence","licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Otvoreni kod (open source)","text":"Softver čiji kod svako može čitati, koristiti i često mijenjati besplatno, po pravilima njegove licence.","also":["open source","open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Licenca otvorenog koda","text":"Pravila koja dolaze uz otvoreni kod. Neka dopuštaju gotovo sve (kao MIT); neka traže da i svoje izmjene podijeliš (kao GPL).","also":["open source licence","open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Vlasnički (proprietary)","text":"U vlasništvu kompanije i nije slobodno za kopiranje ili mijenjanje. Suprotno od otvorenog koda.","also":["proprietary","proprietary software"]},{"id":"copyright","g":"money","word":"Autorsko pravo","text":"Zakonsko pravo stvaraoca da kontroliše kopije svog djela, uključujući kod i tekst.","also":["copyright","copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Intelektualno vlasništvo (IP)","text":"Ideje i tvorevine koje zakon smatra vlasništvom, kao kod, dizajni, imena i logotipi.","also":["IP","intellectual property"]},{"id":"tos","g":"money","word":"Uslovi korištenja","text":"Pravila s kojima se slažeš kad koristiš uslugu.","also":["terms of service","terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Ugovor","text":"Pisani dogovor između dvije strane koji zakon podržava.","also":["contract","contracts"],"noTip":1},{"id":"sow","g":"money","word":"Opis posla (SOW)","text":"Dokument koji tačno navodi koji će se posao uraditi, do kada i za koliko.","also":["SOW","statement of work"]},{"id":"fixedprice","g":"money","word":"Fiksna cijena","text":"Dogovorena cijena za cijeli posao, koliko god dugo trajao.","also":["fixed price","fixed-price"]},{"id":"tm","g":"money","word":"Vrijeme i materijal","text":"Plaćanje stvarno odrađenih sati i stvarno utrošenih stvari, a ne unaprijed zadate cijene.","also":["time and materials","T&M"]},{"id":"invoice","g":"money","word":"Faktura","text":"Račun kojim se traži plaćanje za obavljen posao ili isporučenu robu.","also":["invoice","invoices","fakture"],"noTip":1},{"id":"lockin","g":"money","word":"Vezanost za dobavljača (vendor lock-in)","text":"Kad je odlazak od dobavljača toliko težak ili skup da ostaneš zarobljen kod njega.","also":["vendor lock-in","lock-in"]},{"id":"procurement","g":"money","word":"Nabavka","text":"Proces odabira dobavljača i kupovine od njih.","also":["procurement"]},{"id":"servicecredit","g":"money","word":"Kredit za uslugu","text":"Povrat novca ili popust koji dobiješ kad dobavljač prekrši svoj SLA.","also":["service credit","service credits"]}]}};
